  :root {
    color-scheme: dark;
    --panel: rgba(8, 14, 22, .78);
    --line: rgba(255,255,255,.14);
    --text: #f4f7fb;
    --muted: #91a0b0;
    --accent: #f4b942;
    --blue: #52adff;
    --red: #ff6868;
  }
  * { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
  html, body { margin: 0; width: 100%; height: 100%; overflow: hidden; background: #05080d; font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
  body { touch-action: manipulation; }
  #app { position: fixed; inset: 0; overflow: hidden; background: #05080d; }
  #app::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: 3;
    pointer-events: none;
    background:
      radial-gradient(circle at 50% 44%, transparent 42%, rgba(0,0,0,.22) 76%, rgba(0,0,0,.46) 100%),
      linear-gradient(180deg, rgba(100,150,180,.035), transparent 32%, rgba(4,8,12,.08));
    mix-blend-mode: normal;
  }
  #app::after {
    content: '';
    position: absolute;
    inset: 0;
    z-index: 3;
    pointer-events: none;
    opacity: .08;
    background-image: repeating-linear-gradient(0deg, transparent 0 3px, rgba(255,255,255,.035) 4px);
  }
  canvas { width: 100%; height: 100%; display: block; }

  .topbar {
    position: absolute;
    left: max(12px, env(safe-area-inset-left));
    right: max(12px, env(safe-area-inset-right));
    top: max(10px, env(safe-area-inset-top));
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
    align-items: start;
    gap: 12px;
    pointer-events: none;
    z-index: 8;
  }
  .brand, .round, .spectator, .controls, .status, .mapTag, .hud-actions {
    background: linear-gradient(180deg, rgba(8,14,22,.78), rgba(5,10,16,.70));
    border: 1px solid rgba(255,255,255,.12);
    backdrop-filter: blur(13px);
    -webkit-backdrop-filter: blur(13px);
    box-shadow: 0 12px 34px rgba(0,0,0,.30);
  }
  .brand {
    justify-self: start;
    padding: 7px 10px;
    border-radius: 10px;
    min-width: 0;
    max-width: min(34vw, 220px);
  }
  .eyebrow { font-size: 7px; letter-spacing: .2em; color: var(--accent); font-weight: 900; }
  .brand h1 { margin: 2px 0 0; font-size: 12px; line-height: 1; letter-spacing: .1em; }
  .sub { display: none; }

  .round {
    justify-self: center;
    min-width: min(620px, 60vw);
    border-radius: 12px;
    padding: 7px 12px;
    display: grid;
    grid-template-columns: auto 1fr auto;
    align-items: center;
    gap: 12px;
    text-align: center;
    cursor: pointer;
    pointer-events: auto;
  }
  .round:hover { border-color: rgba(255,255,255,.18); }
  .round-team { display: flex; align-items: center; gap: 10px; min-width: 0; }
  .round-team.right { justify-content: flex-end; }
  .team-score { font-weight: 950; font-size: 24px; line-height: 1; }
  .team-score.blue, .team-alive.blue { color: var(--blue); }
  .team-score.red, .team-alive.red { color: var(--red); }
  .team-alive { font-size: 9px; font-weight: 950; letter-spacing: .09em; white-space: nowrap; }
  .round-mid { display: flex; flex-wrap: wrap; justify-content: center; align-items: center; gap: 6px 8px; min-width: 0; }
  .round-meta { display: flex; justify-content: center; gap: 6px; color: var(--muted); font-size: 8px; font-weight: 900; letter-spacing: .13em; flex-wrap: wrap; }
  .round-meta .current-timer { color: #eef5fb; }
  .tap-hint { color: rgba(255,255,255,.38); font-size: 7px; font-weight: 900; letter-spacing: .16em; white-space: nowrap; }
  .timer { color: #eef5fb; font-size: 11px; font-weight: 900; letter-spacing: .16em; }
  .round.match-point { border-color: rgba(244,185,66,.62); box-shadow: 0 0 26px rgba(244,185,66,.13), 0 12px 34px rgba(0,0,0,.30); }

  .hud-actions {
    justify-self: end;
    display: flex;
    gap: 5px;
    padding: 5px;
    border-radius: 11px;
    pointer-events: auto;
  }
  .hud-actions button {
    min-width: 70px;
    min-height: 34px;
    padding: 0 10px;
    border-radius: 8px;
    font-size: 8px;
  }

  .feed {
    position: absolute;
    z-index: 8;
    right: max(12px, env(safe-area-inset-right));
    top: calc(max(10px, env(safe-area-inset-top)) + 56px);
    width: min(350px, 52vw);
    display: grid;
    justify-items: end;
    gap: 3px;
    padding: 0;
    pointer-events: none;
    opacity: 0;
    visibility: hidden;
    transform: translateX(8px);
    transition: opacity .14s ease, transform .14s ease, visibility 0s linear .14s;
  }
  .feed.show { opacity: 1; visibility: visible; transform: translateX(0); transition-delay: 0s; }
  .feed-row {
    --feed-accent: #f4b942;
    --feed-duration: 6s;
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: flex-end;
    gap: 6px;
    max-width: 100%;
    min-height: 23px;
    padding: 4px 10px 4px 9px;
    border: 0;
    border-right: 2px solid var(--feed-accent);
    border-radius: 2px 0 0 2px;
    background: linear-gradient(90deg, rgba(4,8,13,.22), rgba(4,8,13,.70) 46%, rgba(4,8,13,.86));
    box-shadow: 0 3px 10px rgba(0,0,0,.16);
    color: #edf3f9;
    font-size: 9px;
    font-weight: 780;
    line-height: 1.15;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    text-shadow: 0 1px 2px rgba(0,0,0,.92);
    opacity: 1;
    transform: translateX(0);
    animation: feed-row-life var(--feed-duration) linear forwards;
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
  }
  @keyframes feed-row-life {
    0% { opacity: 0; transform: translateX(9px); }
    4% { opacity: 1; transform: translateX(0); }
    82% { opacity: 1; transform: translateX(0); }
    100% { opacity: 0; transform: translateX(5px); }
  }
  .feed-row::before {
    content: '';
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: linear-gradient(90deg, transparent, rgba(255,255,255,.025));
  }
  .feed-row.system {
    color: #f8dfa3;
    border-right-color: rgba(244,185,66,.80);
    background: linear-gradient(90deg, rgba(40,29,8,.14), rgba(26,20,9,.76));
  }
  .feed-row b, .feed-row span { position: relative; z-index: 1; }
  .feed-row b { color: #fff; overflow: hidden; text-overflow: ellipsis; }
  .feed-row .weapon {
    flex: 0 0 auto;
    padding: 1px 5px 2px;
    border-radius: 2px;
    background: rgba(255,255,255,.075);
    border: 1px solid rgba(255,255,255,.055);
    color: #dce6ef;
    font-size: 7px;
    font-weight: 900;
    letter-spacing: .065em;
    text-shadow: none;
  }
  .feed-row .feed-arrow {
    flex: 0 0 auto;
    color: rgba(255,255,255,.58);
    font-size: 6px;
    line-height: 1;
  }


  .mapTag {
    position: absolute;
    z-index: 8;
    left: max(12px, env(safe-area-inset-left));
    top: calc(max(10px, env(safe-area-inset-top)) + 46px);
    border-radius: 9px;
    padding: 5px 8px;
    pointer-events: none;
    min-width: 0;
    max-width: min(34vw, 220px);
  }
  .mapTag .mode { font-size: 7px; letter-spacing: .16em; font-weight: 900; color: var(--accent); }
  .mapTag .name { margin-top: 1px; font-size: 10px; font-weight: 950; letter-spacing: .04em; }
  .mapTag .desc { display: none; }

  .spectator {
    --team-colour: var(--blue);
    position: absolute;
    z-index: 8;
    left: max(12px, env(safe-area-inset-left));
    bottom: max(12px, env(safe-area-inset-bottom));
    width: min(330px, 48vw);
    min-width: 240px;
    padding: 8px 10px 9px 13px;
    border-radius: 12px;
    pointer-events: none;
    border-left: 3px solid var(--team-colour);
  }
  .spectator-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; }
  .spectator .label { color: var(--accent); font-size: 7px; font-weight: 950; letter-spacing: .18em; }
  .spectator .name { margin-top: 1px; font-size: 15px; line-height: 1; font-weight: 950; }
  .spectator .health-text { color: #edf5fb; font-size: 9px; font-weight: 950; letter-spacing: .1em; white-space: nowrap; }
  .spectator .meta { margin-top: 5px; font-size: 8px; color: var(--muted); display: flex; gap: 8px; flex-wrap: wrap; }
  .health { height: 4px; margin-top: 6px; overflow: hidden; border-radius: 99px; background: rgba(255,255,255,.11); }
  .health > i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg,#d94242,#f2c14e,#58d68d); transform-origin: left; }

  .status {
    position: absolute;
    z-index: 9;
    left: 50%;
    top: calc(max(10px, env(safe-area-inset-top)) + 92px);
    transform: translateX(-50%);
    border-radius: 9px;
    padding: 6px 10px;
    font-size: 9px;
    font-weight: 950;
    letter-spacing: .14em;
    opacity: 0;
    visibility: hidden;
    transition: opacity .18s ease, visibility 0s linear .18s;
    pointer-events: none;
  }
  .status.show { opacity: 1; visibility: visible; transition-delay: 0s; }
  .feed[hidden], .status[hidden] { display: none !important; }

  .controls {
    position: absolute;
    z-index: 9;
    left: 50%;
    bottom: max(12px, env(safe-area-inset-bottom));
    transform: translateX(-50%);
    width: min(390px, 43vw);
    display: grid;
    grid-template-columns: 1fr 1.18fr 1fr;
    gap: 5px;
    padding: 5px;
    border-radius: 12px;
  }
  button {
    appearance: none;
    border: 1px solid rgba(255,255,255,.13);
    color: #fff;
    background: rgba(255,255,255,.065);
    min-height: 38px;
    border-radius: 9px;
    font: inherit;
    font-weight: 900;
    font-size: 9px;
    letter-spacing: .06em;
  }
  button:active { transform: scale(.98); background: rgba(255,255,255,.13); }
  button.primary { background: linear-gradient(180deg, rgba(244,185,66,.28), rgba(244,185,66,.11)); border-color: rgba(244,185,66,.46); }

  @media (max-width: 760px) {
    .round { min-width: min(540px, 66vw); padding-inline: 10px; gap: 8px; }
    .team-score { font-size: 20px; }
    .team-alive { font-size: 8px; }
    .round-meta { font-size: 7px; }
    .tap-hint { display: none; }
    .hud-actions button { min-width: 58px; padding-inline: 8px; }
    .spectator { width: min(285px, 50vw); min-width: 215px; }
    .controls { width: min(330px, 44vw); }
  }


  .crosshair {
    --crosshair-gap: 7px;
    --hit-alpha: 0;
    position: absolute;
    left: 50%;
    top: 48%;
    width: 54px;
    height: 54px;
    transform: translate(-50%, -50%);
    z-index: 5;
    pointer-events: none;
    filter: drop-shadow(0 1px 2px rgba(0,0,0,.8));
  }
  .crosshair > i { position: absolute; display: block; background: rgba(255,255,255,.84); border-radius: 2px; }
  .crosshair .left { width: 8px; height: 2px; left: calc(50% - var(--crosshair-gap) - 8px); top: calc(50% - 1px); }
  .crosshair .right { width: 8px; height: 2px; left: calc(50% + var(--crosshair-gap)); top: calc(50% - 1px); }
  .crosshair .top { width: 2px; height: 8px; left: calc(50% - 1px); top: calc(50% - var(--crosshair-gap) - 8px); }
  .crosshair .bottom { width: 2px; height: 8px; left: calc(50% - 1px); top: calc(50% + var(--crosshair-gap)); }
  .crosshair::before, .crosshair::after {
    content: '';
    position: absolute;
    left: 50%;
    top: 50%;
    width: 22px;
    height: 2px;
    background: rgba(255,255,255,var(--hit-alpha));
    border-radius: 2px;
    transform-origin: center;
  }
  .crosshair::before { transform: translate(-50%,-50%) rotate(45deg); }
  .crosshair::after { transform: translate(-50%,-50%) rotate(-45deg); }
  .crosshair.hidden { opacity: 0; }

  .round-result {
    position: absolute;
    left: 50%;
    top: 30%;
    transform: translate(-50%, -50%);
    z-index: 7;
    min-width: min(360px, 84vw);
    padding: 16px 20px;
    border-radius: 16px;
    border: 1px solid rgba(255,255,255,.16);
    background: linear-gradient(180deg, rgba(10,18,28,.92), rgba(5,10,16,.88));
    box-shadow: 0 22px 70px rgba(0,0,0,.54);
    text-align: center;
    pointer-events: none;
    opacity: 0;
    visibility: hidden;
    transition: opacity .2s ease, transform .2s ease, visibility 0s linear .2s;
  }
  .round-result.show { opacity: 1; visibility: visible; transform: translate(-50%, -46%); transition-delay: 0s; }
  .round-result .kicker { color: var(--accent); font-size: 9px; font-weight: 900; letter-spacing: .2em; }
  .round-result strong { display: block; margin-top: 5px; font-size: 22px; letter-spacing: .06em; }
  .round-result span { display: block; margin-top: 5px; color: var(--muted); font-size: 11px; }


  .damage-overlay {
    position: absolute;
    inset: 0;
    z-index: 4;
    pointer-events: none;
    opacity: 0;
    background: radial-gradient(circle at center, rgba(120,0,0,0) 24%, rgba(150,0,0,.18) 66%, rgba(185,0,0,.72) 100%);
    transition: opacity .05s linear;
  }
  .death-overlay {
    position: absolute;
    inset: 0;
    z-index: 6;
    display: grid;
    place-items: center;
    text-align: center;
    pointer-events: none;
    opacity: 0;
    visibility: hidden;
    background: rgba(12,0,0,.48);
    transition: opacity .18s ease, visibility 0s linear .18s;
  }
  .death-overlay.show { opacity: 1; visibility: visible; transition-delay: 0s; }
  .death-overlay strong { display: block; font-size: 24px; letter-spacing: .08em; }
  .death-overlay span { display: block; margin-top: 5px; color: rgba(255,255,255,.66); font-size: 12px; }

  .rotate-note { display: none; position: absolute; inset: 0; place-items: center; background: #05080d; z-index: 20; padding: 28px; text-align: center; }
  .rotate-note div { max-width: 320px; }
  .rotate-note strong { display: block; font-size: 22px; margin-bottom: 8px; }
  .rotate-note span { color: var(--muted); font-size: 13px; }
  .build-stamp {
    position: absolute;
    right: max(14px, env(safe-area-inset-right));
    bottom: max(14px, env(safe-area-inset-bottom));
    z-index: 18;
    padding: 5px 8px;
    border: 1px solid rgba(255,255,255,.12);
    border-radius: 9px;
    background: rgba(5,10,16,.62);
    color: rgba(220,232,242,.64);
    font-size: 8px;
    font-weight: 850;
    letter-spacing: .12em;
    pointer-events: none;
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    display: none;
  }

  .scoreboard-overlay {
    position: absolute;
    inset: 0;
    z-index: 14;
    display: grid;
    place-items: center;
    padding: max(16px, env(safe-area-inset-top) + 12px) max(16px, env(safe-area-inset-right) + 12px) max(16px, env(safe-area-inset-bottom) + 12px) max(16px, env(safe-area-inset-left) + 12px);
    background: rgba(3, 7, 12, .58);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
  }
  .scoreboard-overlay[hidden] { display: none !important; }
  .scoreboard-card {
    width: min(900px, 94vw);
    max-height: min(78vh, 760px);
    overflow: auto;
    border-radius: 18px;
    padding: 16px;
    background: linear-gradient(180deg, rgba(10,18,28,.94), rgba(5,10,16,.92));
    border: 1px solid rgba(255,255,255,.14);
    box-shadow: 0 28px 80px rgba(0,0,0,.48);
  }
  .scoreboard-header { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-bottom: 12px; }
  .scoreboard-header .kicker { color: var(--accent); font-size: 9px; font-weight: 900; letter-spacing: .18em; }
  .scoreboard-header strong { display: block; font-size: 24px; letter-spacing: .05em; }
  .scoreboard-close { min-height: 38px; min-width: 88px; }
  .scoreboard-summary { color: var(--muted); font-size: 11px; margin-top: 4px; }
  .scoreboard-teams { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
  .scoreboard-team {
    background: rgba(255,255,255,.035);
    border: 1px solid rgba(255,255,255,.08);
    border-radius: 15px;
    overflow: hidden;
  }
  .scoreboard-team-head { display: flex; justify-content: space-between; align-items: center; padding: 12px 14px; font-size: 12px; font-weight: 950; letter-spacing: .12em; }
  .scoreboard-team.blue .scoreboard-team-head { color: var(--blue); background: rgba(82,173,255,.08); }
  .scoreboard-team.red .scoreboard-team-head { color: var(--red); background: rgba(255,104,104,.08); }
  .scoreboard-cols, .scoreboard-row {
    display: grid;
    grid-template-columns: minmax(0, 1.7fr) 52px 52px 54px minmax(74px, .85fr) minmax(72px, .9fr);
    gap: 8px;
    align-items: center;
    padding: 8px 14px;
  }
  .scoreboard-cols {
    color: rgba(255,255,255,.48);
    font-size: 9px;
    font-weight: 900;
    letter-spacing: .14em;
    border-top: 1px solid rgba(255,255,255,.07);
    border-bottom: 1px solid rgba(255,255,255,.07);
    background: rgba(255,255,255,.02);
  }
  .scoreboard-row { font-size: 11px; color: #ebf3fa; border-bottom: 1px solid rgba(255,255,255,.05); }
  .scoreboard-row:last-child { border-bottom: 0; }
  .scoreboard-row .name { display: flex; align-items: center; gap: 7px; min-width: 0; font-weight: 850; overflow: hidden; white-space: nowrap; }
  .scoreboard-row .name b { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .scoreboard-life-indicator {
    flex: 0 0 auto;
    display: inline-grid;
    place-items: center;
    width: 15px;
    height: 15px;
    border-radius: 50%;
    font-style: normal;
    font-size: 10px;
    font-weight: 950;
    line-height: 1;
  }
  .scoreboard-life-indicator.alive {
    color: #8af0b5;
    border: 1px solid rgba(97,223,170,.54);
    background: rgba(35,114,78,.28);
    box-shadow: 0 0 9px rgba(97,223,170,.18);
  }
  .scoreboard-life-indicator.dead {
    color: #ff9a90;
    border: 1px solid rgba(255,104,104,.58);
    border-radius: 5px;
    background: rgba(121,39,39,.34);
    font-size: 12px;
    text-shadow: 0 0 7px rgba(255,104,104,.28);
  }
  .scoreboard-row .weapon, .scoreboard-row .status { color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .scoreboard-row.dead { opacity: .72; }
  .show-ui-btn {
    position: absolute;
    z-index: 16;
    right: max(12px, env(safe-area-inset-right));
    top: calc(max(10px, env(safe-area-inset-top)) + 12px);
    min-height: 38px;
    min-width: 96px;
    padding: 0 14px;
    border-radius: 11px;
    border-color: rgba(244,185,66,.58);
    background: linear-gradient(180deg, rgba(63,47,17,.96), rgba(28,22,11,.94));
    box-shadow: 0 10px 30px rgba(0,0,0,.38), 0 0 22px rgba(244,185,66,.13);
    color: #fff3d2;
    font-weight: 950;
    letter-spacing: .10em;
    display: none;
    touch-action: manipulation;
  }
  .show-ui-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }
  /* The spectator HUD toggle intentionally removes only the four panels
     highlighted by the user: branding, map label, operator card and camera
     controls. The score strip, action buttons, kill feed, crosshair and combat
     feedback remain visible. */
  body[data-ui-buttons='hidden'] .brand,
  body[data-ui-buttons='hidden'] .mapTag,
  body[data-ui-buttons='hidden'] .spectator,
  body[data-ui-buttons='hidden'] .controls { display: none !important; }
  body[data-ui-buttons='hidden'] .show-ui-btn { display: none !important; }
  body[data-ui-buttons='hidden'] .topbar { grid-template-columns: minmax(0, 1fr) auto; gap: 10px; }
  body[data-ui-buttons='hidden'] .round { grid-column: 1 / 2; justify-self: start; min-width: min(540px, 64vw); }
  body[data-ui-buttons='hidden'] .hud-actions { grid-column: 2 / 3; justify-self: end; margin-left: auto; }
  body[data-app-state='menu'] .scoreboard-overlay,
  body[data-app-state='menu'] .show-ui-btn { display: none !important; }
  @media (max-width: 900px) {
    .scoreboard-teams { grid-template-columns: 1fr; }
  }
  @media (max-width: 700px) {
    .scoreboard-card { padding: 12px; }
    .scoreboard-header strong { font-size: 20px; }
    .scoreboard-cols, .scoreboard-row { grid-template-columns: minmax(0,1.45fr) 40px 40px 44px minmax(62px,.8fr) minmax(64px,.8fr); gap: 6px; padding-inline: 10px; }
    .scoreboard-row { font-size: 10px; }
  }

  .menu-shell {
    position: absolute;
    inset: 0;
    z-index: 15;
    display: grid;
    align-items: stretch;
    overflow: auto;
    overscroll-behavior: contain;
    background:
      radial-gradient(circle at 76% 28%, rgba(50,92,118,.18), transparent 34%),
      linear-gradient(90deg, rgba(3,7,12,.90) 0%, rgba(4,9,15,.74) 48%, rgba(4,8,12,.54) 100%);
  }
  .menu-shell[hidden] { display: none !important; }
  .menu-layout {
    display: grid;
    grid-template-columns: minmax(226px, 286px) minmax(0, 1fr);
    gap: 12px;
    padding: max(16px, env(safe-area-inset-top) + 14px) max(16px, env(safe-area-inset-right) + 14px) max(18px, env(safe-area-inset-bottom) + 18px) max(16px, env(safe-area-inset-left) + 14px);
    min-height: 100%;
    height: max-content;
  }
  .menu-sidebar, .menu-content {
