    margin: 0 auto 18px;
    transform-style: preserve-3d;
    transform: perspective(900px) rotateX(-11deg) rotateY(-11deg);
    filter: drop-shadow(0 24px 28px rgba(0,0,0,.52));
  }
  .career-crate-core::before,
  .career-crate-core::after {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: 6px;
    pointer-events: none;
  }
  .career-crate-core::before {
    background:
      linear-gradient(180deg, rgba(255,219,148,.28), rgba(255,219,148,0) 20%),
      linear-gradient(180deg, rgba(60,72,84,.94), rgba(32,39,47,.98));
    border: 1px solid rgba(255,208,109,.42);
    box-shadow:
      0 12px 28px rgba(0,0,0,.42),
      inset 0 1px rgba(255,243,206,.22),
      inset 0 -12px 18px rgba(0,0,0,.32);
    clip-path: polygon(7% 10%, 93% 10%, 100% 34%, 100% 100%, 0 100%, 0 34%);
    transform: translateZ(0);
  }
  .career-crate-core::after {
    inset: -4px 10px auto 10px;
    height: 48px;
    background:
      linear-gradient(180deg, rgba(255,224,164,.20), rgba(255,224,164,0) 24%),
      linear-gradient(180deg, rgba(100,114,127,.97), rgba(54,61,70,.98));
    border: 1px solid rgba(255,208,109,.48);
    box-shadow: inset 0 1px rgba(255,244,210,.24), 0 8px 16px rgba(0,0,0,.22);
    transform-origin: 50% 96%;
    transform: translateZ(18px) rotateX(0deg);
    transition: transform .42s cubic-bezier(.16,.8,.25,1.2), box-shadow .3s ease;
  }
  .career-crate-core i {
    position: absolute;
    top: 56px;
    width: 28px;
    height: 34px;
    border: 1px solid rgba(255,208,109,.62);
    border-radius: 4px;
    background:
      linear-gradient(180deg, rgba(244,185,66,.34), rgba(116,74,12,.92));
    box-shadow: 0 0 10px rgba(244,185,66,.20), inset 0 1px rgba(255,244,209,.32);
    transform: translateZ(14px);
