  .career-crate-core i::before {
    content: '';
    position: absolute;
    inset: 7px 8px;
    border-radius: 2px;
    background: rgba(29,22,10,.58);
    box-shadow: inset 0 1px rgba(255,244,210,.14);
  }
  .career-crate-core i:first-child { left: 28px; }
  .career-crate-core i:nth-child(2) { left: calc(50% - 14px); }
  .career-crate-core i:last-child { right: 28px; }
  .career-crate-overlay.opening .career-crate-core,
  .career-crate-overlay.revealed .career-crate-core { animation: careerCratePulse .28s ease-in-out infinite alternate; }
  .career-crate-overlay.opening .career-crate-core::after,
  .career-crate-overlay.revealed .career-crate-core::after {
    transform: translateZ(18px) rotateX(-76deg) translateY(-8px);
