  @keyframes careerCratePulse {
    to { transform: perspective(900px) rotateX(-10deg) rotateY(-9deg) translateY(-2px) scale(1.02); filter: brightness(1.06) drop-shadow(0 28px 34px rgba(0,0,0,.58)); }
