  transform: skewX(-42deg);
  transform-origin: left bottom;
}
.career-crate-body::after {
  top: -14px;
  right: -18px;
  width: 18px;
  height: 110px;
  border: 1px solid rgba(255,215,134,.22);
  border-left: 0;
