  transition: transform .46s cubic-bezier(.16,.8,.25,1.2), box-shadow .30s ease;
}
.career-crate-lid::before {
  left: 8px;
  right: 10px;
  top: -18px;
  height: 18px;
  border: 1px solid rgba(255,227,168,.22);
  border-bottom: 0;
  border-radius: 6px 6px 0 0;
