.career-crate-band.band-left,
.career-crate-lid-band.band-left { left: 18px; }
.career-crate-band.band-mid,
.career-crate-lid-band.band-mid { left: calc(50% - 9px); }
.career-crate-band.band-right,
.career-crate-lid-band.band-right { right: 18px; }
.career-crate-latch,
.career-crate-hinge {
