  border: 1px solid rgba(255,214,122,.58);
  background: linear-gradient(180deg, rgba(243,190,83,.34), rgba(116,75,14,.96));
  box-shadow: inset 0 1px rgba(255,247,222,.30), 0 6px 10px rgba(0,0,0,.18);
}
.career-crate-latch {
  bottom: 64px;
