}
.career-crate-hinge.hinge-left { left: 76px; }
.career-crate-hinge.hinge-right { right: 78px; }
.career-crate-glow {
  position: absolute;
  left: 50%;
  bottom: 68px;
  width: 168px;
  height: 82px;
  transform: translateX(-50%);
  background: radial-gradient(circle at 50% 72%, rgba(255,210,120,.44), rgba(255,210,120,0) 68%);
