}
.career-crate-overlay.revealed .career-crate-core {
  transform: perspective(1200px) rotateX(-12deg) rotateY(-22deg) translateY(-4px) scale(1.03);
  filter: drop-shadow(0 30px 34px rgba(0,0,0,.62));
}
.career-crate-overlay.revealed .career-crate-lid {
  transform: translateZ(2px) rotateX(-112deg) translateY(-6px);
