.career-crate-overlay.revealed .career-crate-body {
  border-color: rgba(97,223,170,.56);
  box-shadow: 0 14px 22px rgba(0,0,0,.32), 0 0 30px rgba(97,223,170,.12), inset 0 1px rgba(255,243,204,.18), inset 0 -12px 18px rgba(0,0,0,.36);
}
.career-crate-model {
