@keyframes careerUnifiedWeaponScan109 {
  from { opacity: .18; transform: translate3d(34px, -6px, 0) rotateX(-10deg) rotateY(-44deg) scale(.55); filter: blur(3px) brightness(1.8); }
  to { opacity: 1; transform: translate3d(0, -6px, 0) rotateX(-10deg) rotateY(-30deg) scale(.62); filter: blur(0) brightness(1.16); }
