    repeating-linear-gradient(135deg, rgba(185,194,198,.18) 0 9px, rgba(107,29,28,.34) 9px 14px, transparent 14px 25px),
    linear-gradient(145deg, #727b80, #333b40 45%, #10161a 82%);
}
.career-weapon-rig.skin-urban-grid .career-weapon-cuboid.polymer .face,
.career-weapon-rig.skin-urban-grid .career-weapon-cuboid.worn-polymer .face {
  background:
