/* Build 11.3: simulated matchmaking, management-style command UI and WebGL reward crate. */
:root {
  --manager-navy: #07131c;
  --manager-panel: #0c1b27;
  --manager-panel-2: #102431;
  --manager-line: rgba(154, 190, 207, .20);
  --manager-accent: #42c7a7;
  --manager-accent-soft: rgba(66, 199, 167, .16);
}

/* Dense football-management-inspired command structure: persistent status bar,
   flat navigation rail and information-first content panels. */
.menu-shell {
  grid-template-rows: 62px minmax(0, 1fr);
  overflow: hidden;
  background:
    linear-gradient(180deg, rgba(7,19,28,.98), rgba(4,10,16,.98)),
    repeating-linear-gradient(90deg, transparent 0 79px, rgba(91,142,165,.025) 80px);
}
.menu-shell::before,
.menu-shell::after { opacity: .18; }
.manager-topbar {
  position: relative;
  z-index: 8;
  width: 100%;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  display: grid;
  grid-template-columns: minmax(230px, 286px) minmax(0, 1fr) minmax(210px, 270px);
  align-items: stretch;
  min-width: 0;
  border-bottom: 1px solid rgba(126,178,198,.28);
  background: linear-gradient(90deg, #061019, #0b1c28 52%, #07141e);
  box-shadow: 0 8px 28px rgba(0,0,0,.34);
}
.manager-brand,
.manager-context,
.manager-profile {
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 8px 18px;
}
.manager-brand {
  border-right: 1px solid rgba(126,178,198,.18);
  background: linear-gradient(110deg, rgba(66,199,167,.15), transparent 72%);
}
.manager-brand span,
.manager-context span,
.manager-profile span {
  color: rgba(181,207,219,.64);
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .18em;
}
.manager-brand strong,
.manager-context strong,
.manager-profile strong {
  overflow: hidden;
  color: #f2f8fb;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 13px;
  font-weight: 950;
  letter-spacing: .08em;
}
.manager-brand strong { color: var(--manager-accent); font-size: 15px; }
.manager-brand small,
.manager-context small,
.manager-profile small {
  overflow: hidden;
  color: rgba(177,201,213,.56);
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 7px;
  font-weight: 800;
  letter-spacing: .10em;
}
.manager-context { border-right: 1px solid rgba(126,178,198,.14); }
.manager-context strong { margin: 2px 0; }
.manager-profile { text-align: right; background: rgba(255,255,255,.018); }
.manager-profile strong { color: #f1c65b; }

.menu-layout {
  width: 100%;
  min-width: 0;
  max-width: 100%;
  height: 100%;
  min-height: 0;
  margin: 0;
  padding: 0;
  grid-template-columns: minmax(228px, 270px) minmax(0, 1fr);
  gap: 0;
  perspective: none;
}
.menu-sidebar,
.menu-content {
  border-radius: 0;
  clip-path: none;
  border: 0;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}
.menu-sidebar {
  padding: 16px 13px 14px;
  border-right: 1px solid rgba(130,180,199,.22);
  background:
    linear-gradient(180deg, #0a1924, #07131c),
    repeating-linear-gradient(180deg, transparent 0 39px, rgba(255,255,255,.018) 40px);
  box-shadow: 12px 0 32px rgba(0,0,0,.22);
  clip-path: none;
}
.menu-sidebar::before { display: none; }
.menu-command-mark {
  padding: 2px 7px 12px;
  border-bottom: 1px solid rgba(126,178,198,.18);
}
.menu-command-mark::after { display: none; }
.menu-title {
  margin-top: 5px;
  font-size: 21px;
  line-height: 1.05;
  letter-spacing: .035em;
  text-shadow: none;
}
.menu-subtitle { margin-top: 6px; font-size: 9px; line-height: 1.35; }
.menu-nav { gap: 2px; margin-top: 0; }
.menu-tab {
  min-height: 54px;
  grid-template-columns: 27px minmax(0, 1fr) 15px;
  gap: 8px;
  padding: 8px 10px;
  border: 0;
  border-left: 3px solid transparent;
  clip-path: none;
  background: transparent;
  box-shadow: none;
  transform: none;
}
.menu-tab::before { display: none; }
.menu-tab:hover {
  transform: none;
  filter: none;
  background: rgba(255,255,255,.045);
}
.menu-tab.active,
.menu-tab.primary {
  transform: none;
  border-left-color: var(--manager-accent);
  background: linear-gradient(90deg, var(--manager-accent-soft), rgba(66,199,167,.035));
  box-shadow: inset 0 1px rgba(255,255,255,.035);
}
.menu-tab-index { color: rgba(174,204,216,.42); font-size: 8px; }
.menu-tab-copy strong { font-size: 9px; letter-spacing: .12em; }
.menu-tab-copy small { margin-top: 3px; font-size: 7px; }
.menu-tab-chevron { font-size: 17px; }
.menu-tab.active .menu-tab-index,
.menu-tab.active .menu-tab-chevron { color: var(--manager-accent); }
.menu-side-actions {
  position: static;
  gap: 4px;
  padding: 10px 0 0;
  background: transparent;
}
.menu-side-actions button,
.menu-return-btn {
  min-height: 38px;
  border-radius: 2px;
  clip-path: none;
  box-shadow: none;
  font-size: 8px;
}
.menu-side-actions button.primary,
.menu-return-btn.primary {
  border-color: rgba(66,199,167,.56);
  background: linear-gradient(180deg, rgba(66,199,167,.28), rgba(32,112,96,.34));
  color: #eafff9;
}
.menu-content {
  width: 100%;
  min-width: 0;
  max-width: 100%;
  margin: 0;
  padding: 0 20px 20px;
  clip-path: none;
  gap: 10px;
  background: linear-gradient(180deg, rgba(9,22,31,.98), rgba(5,13,20,.98));
  box-shadow: none;
}
.menu-content::before {
  border-radius: 0;
  background:
    linear-gradient(135deg, rgba(66,199,167,.045), transparent 28%),
    repeating-linear-gradient(90deg, transparent 0 119px, rgba(103,155,177,.022) 120px);
}
.menu-header-row {
  top: 0;
  min-height: 52px;
  margin: 0 -20px;
