/* Simulated network lobby. */
.matchmaking-overlay {
  position: fixed;
  inset: 0;
  z-index: 90;
  display: grid;
  place-items: center;
  padding: max(16px, env(safe-area-inset-top)) max(16px, env(safe-area-inset-right)) max(16px, env(safe-area-inset-bottom)) max(16px, env(safe-area-inset-left));
  background: rgba(2,8,13,.88);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}
.matchmaking-overlay[hidden] { display: none !important; }
.matchmaking-card {
  width: min(1120px, 96vw);
  max-height: min(820px, 94vh);
  max-height: min(820px, 94dvh);
  overflow: auto;
  border: 1px solid rgba(117,174,195,.34);
  border-top: 3px solid var(--manager-accent);
  border-radius: 3px;
  background: linear-gradient(180deg, #0b1b27, #06121b);
  box-shadow: 0 34px 100px rgba(0,0,0,.66);
}
.matchmaking-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  align-items: center;
  padding: 18px 20px;
  border-bottom: 1px solid rgba(124,174,194,.20);
  background: linear-gradient(90deg, rgba(66,199,167,.09), transparent 48%);
}
.matchmaking-kicker,
.matchmaking-search-copy > span,
.matchmaking-map-card span,
.matchmaking-lobby-head span,
.matchmaking-queue-time span {
  color: var(--manager-accent);
  font-size: 8px;
  font-weight: 950;
  letter-spacing: .17em;
}
.matchmaking-header h2 { margin: 4px 0 2px; font-size: clamp(22px, 4vw, 38px); letter-spacing: .03em; }
.matchmaking-header p { margin: 0; color: rgba(190,211,220,.66); font-size: 10px; }
.matchmaking-queue-time { min-width: 138px; padding-left: 18px; border-left: 1px solid rgba(124,174,194,.20); text-align: right; }
.matchmaking-queue-time strong { display: block; font-size: 25px; letter-spacing: .08em; }
.matchmaking-queue-time small { color: rgba(190,211,220,.54); font-size: 8px; letter-spacing: .10em; }
.matchmaking-body {
  display: grid;
  grid-template-columns: minmax(280px, .78fr) minmax(500px, 1.38fr);
  gap: 1px;
  background: rgba(126,178,198,.16);
}
.matchmaking-search-panel,
.matchmaking-lobby-panel { background: #091923; }
.matchmaking-search-panel { padding: 22px; display: grid; align-content: start; gap: 18px; }
.matchmaking-radar {
  position: relative;
  width: min(224px, 55vw);
  aspect-ratio: 1;
  margin: 2px auto 0;
  border: 1px solid rgba(66,199,167,.38);
  border-radius: 50%;
  overflow: hidden;
  background:
    radial-gradient(circle, transparent 0 23%, rgba(66,199,167,.16) 24% 24.8%, transparent 25.5% 48%, rgba(66,199,167,.13) 49% 49.8%, transparent 50.5% 74%, rgba(66,199,167,.11) 75% 75.8%, transparent 76%),
    linear-gradient(rgba(66,199,167,.12) 1px, transparent 1px),
    linear-gradient(90deg, rgba(66,199,167,.12) 1px, transparent 1px),
    #07151e;
  background-size: auto, 25% 25%, 25% 25%, auto;
  box-shadow: inset 0 0 34px rgba(66,199,167,.08), 0 0 34px rgba(0,0,0,.28);
}
.matchmaking-radar::before,
.matchmaking-radar::after {
  content: '';
  position: absolute;
  left: 50%;
  top: 50%;
  background: rgba(66,199,167,.22);
  transform: translate(-50%,-50%);
}
.matchmaking-radar::before { width: 1px; height: 100%; }
.matchmaking-radar::after { width: 100%; height: 1px; }
.matchmaking-radar i {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: conic-gradient(from 0deg, rgba(66,199,167,.42), rgba(66,199,167,.03) 25%, transparent 32%);
  animation: matchmakingRadarSweep 1.55s linear infinite;
}
.matchmaking-radar b,
.matchmaking-radar span {
  position: absolute;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #7ff4d4;
  box-shadow: 0 0 12px #55d9b8;
}
.matchmaking-radar b { left: 32%; top: 39%; animation: matchmakingPing 1.25s ease-in-out infinite; }
.matchmaking-radar span { right: 25%; bottom: 31%; animation: matchmakingPing 1.25s .55s ease-in-out infinite; }
@keyframes matchmakingRadarSweep { to { transform: rotate(360deg); } }
@keyframes matchmakingPing { 50% { opacity: .22; transform: scale(.55); } }
.matchmaking-search-copy { text-align: center; }
.matchmaking-search-copy strong { display: block; margin-top: 5px; font-size: 14px; letter-spacing: .04em; }
.matchmaking-search-copy small { display: block; margin-top: 5px; color: rgba(190,211,220,.52); font-size: 7px; letter-spacing: .12em; }
.matchmaking-map-card { display: grid; gap: 1px; border: 1px solid rgba(124,174,194,.16); background: rgba(124,174,194,.14); }
.matchmaking-map-card > div { display: flex; justify-content: space-between; gap: 10px; padding: 10px 11px; background: #0c202c; }
.matchmaking-map-card strong { font-size: 9px; letter-spacing: .07em; text-align: right; }
.matchmaking-lobby-panel { padding: 16px; }
.matchmaking-lobby-head { display: flex; justify-content: space-between; gap: 10px; padding: 2px 2px 12px; }
.matchmaking-lobby-head strong { color: #f1c65b; font-size: 9px; letter-spacing: .10em; }
.matchmaking-team-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.matchmaking-team { min-width: 0; border: 1px solid rgba(124,174,194,.16); background: rgba(4,13,19,.52); }
.matchmaking-team.blue { border-top: 3px solid #50b8ef; }
.matchmaking-team.red { border-top: 3px solid #f16f76; }
.matchmaking-team > header { display: flex; justify-content: space-between; gap: 8px; padding: 10px; background: rgba(255,255,255,.035); }
.matchmaking-team > header span { font-size: 9px; font-weight: 950; letter-spacing: .12em; }
.matchmaking-team > header b { color: rgba(193,213,221,.62); font-size: 7px; letter-spacing: .10em; }
.matchmaking-roster-row {
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr) 42px 62px;
  gap: 7px;
  align-items: center;
  min-height: 54px;
  padding: 7px 9px;
  border-top: 1px solid rgba(124,174,194,.10);
  opacity: .44;
}
.matchmaking-roster-row.found { opacity: 1; }
.matchmaking-roster-row.ready { background: linear-gradient(90deg, rgba(66,199,167,.10), transparent); }
.matchmaking-slot { color: rgba(183,207,217,.38); font-size: 8px; }
.matchmaking-roster-row strong,
.matchmaking-roster-row small { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.matchmaking-roster-row strong { font-size: 9px; letter-spacing: .06em; }
.matchmaking-roster-row small { margin-top: 3px; color: rgba(188,209,218,.50); font-size: 7px; letter-spacing: .05em; }
.matchmaking-ping { color: rgba(188,209,218,.54); font-size: 7px; text-align: right; }
.matchmaking-roster-row b { color: rgba(188,209,218,.46); font-size: 7px; text-align: right; letter-spacing: .08em; }
.matchmaking-roster-row.ready b { color: var(--manager-accent); }
.matchmaking-stages {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  border-top: 1px solid rgba(124,174,194,.18);
  border-bottom: 1px solid rgba(124,174,194,.18);
  background: #081822;
}
.matchmaking-stages > div { position: relative; min-width: 0; padding: 12px 10px 11px 28px; border-right: 1px solid rgba(124,174,194,.13); opacity: .38; }
.matchmaking-stages > div:last-child { border-right: 0; }
.matchmaking-stages i { position: absolute; left: 10px; top: 50%; width: 9px; height: 9px; transform: translateY(-50%); border: 1px solid rgba(184,210,219,.45); border-radius: 50%; }
.matchmaking-stages span,
.matchmaking-stages small { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.matchmaking-stages span { font-size: 8px; font-weight: 950; letter-spacing: .10em; }
.matchmaking-stages small { margin-top: 2px; color: rgba(185,207,217,.48); font-size: 6px; letter-spacing: .08em; }
.matchmaking-stages > div.active,
.matchmaking-stages > div.complete { opacity: 1; }
.matchmaking-stages > div.active i { border-color: #f1c65b; background: #f1c65b; box-shadow: 0 0 12px rgba(241,198,91,.58); }
.matchmaking-stages > div.complete i { border-color: var(--manager-accent); background: var(--manager-accent); }
.matchmaking-footer { display: grid; grid-template-columns: minmax(0, 1fr) auto auto; gap: 14px; align-items: center; padding: 14px 18px; }
.matchmaking-progress { height: 7px; overflow: hidden; border: 1px solid rgba(124,174,194,.20); background: #041017; }
.matchmaking-progress i { display: block; width: 0; height: 100%; background: linear-gradient(90deg, #2aa58a, #62e7c2); box-shadow: 0 0 14px rgba(66,199,167,.32); transition: width .12s linear; }
.matchmaking-footer > strong { min-width: 112px; color: #f1c65b; font-size: 9px; text-align: right; letter-spacing: .10em; }
.matchmaking-footer button { min-width: 132px; border-radius: 2px; }
.matchmaking-footer button:disabled { opacity: .48; }

/* True 3D field crate. The old CSS cuboid is fully disabled; the canvas is
   rendered by the same custom WebGL technique used by the match. */
.career-crate-display { min-height: 290px; }
.career-crate-core {
  position: relative;
  display: block;
  width: min(520px, 88vw);
  height: 290px;
  margin: 0 auto;
  transform: none !important;
  filter: none !important;
  animation: none !important;
  background: transparent !important;
  perspective: none !important;
}
.career-crate-core::before,
.career-crate-core::after { display: none !important; }
.career-crate-canvas {
  display: block;
  width: 100%;
  height: 100%;
  cursor: grab;
  touch-action: none;
  filter: drop-shadow(0 28px 26px rgba(0,0,0,.48));
}
.career-crate-canvas.dragging { cursor: grabbing; }
.career-crate-renderer-fallback {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  border: 1px solid rgba(244,185,66,.32);
  color: rgba(224,197,132,.76);
  font-size: 9px;
  letter-spacing: .14em;
}
.career-crate-renderer-fallback[hidden] { display: none !important; }
.career-crate-overlay.cycling .career-crate-core { display: none !important; }
.career-crate-overlay.closed .career-crate-model,
.career-crate-overlay.opening .career-crate-model { display: none !important; }
.career-crate-overlay.revealed .career-crate-core { opacity: .76; }
.career-crate-overlay.revealed .career-crate-model { z-index: 6; }
.career-crate-overlay.revealed .career-crate-model .career-weapon-mini3d.crate .career-weapon-rig {
  transform: translate3d(0, -62px, 0) rotateX(-8deg) rotateY(-24deg) scale(.62);
}

