.team-trait-list { display: flex; flex-wrap: wrap; gap: 5px; }
.team-trait-list span { padding: 6px 8px; border: 1px solid rgba(91, 182, 237, .22); background: rgba(20, 61, 85, .34); color: #bfe9ff; font-size: 7px; }
.team-role-note { margin: 0; color: #9bacb8; font-size: 8px; line-height: 1.45; }
