.team-history-head { padding: 7px 8px; background: rgba(255,255,255,.04); color: #708696; font-size: 6px; letter-spacing: .1em; }
.team-history-row { padding: 8px; border-bottom: 1px solid rgba(255,255,255,.055); color: #aebcc6; font-size: 7px; }
