/* Build 11.10: individual squad loadout management. */
.career-squad-loadout-panel {
  margin: 10px 0;
  padding: 12px;
  min-width: 0;
  overflow: hidden;
  border: 1px solid rgba(126,170,199,.22);
  background: linear-gradient(145deg, rgba(15,28,39,.94), rgba(4,10,16,.96));
  box-shadow: inset 0 1px rgba(255,255,255,.04), 0 14px 30px rgba(0,0,0,.18);
}
.career-armoury-player-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
}
.career-armoury-player {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas:
    "slot rating"
    "copy rating"
    "action action";
  align-items: center;
  gap: 4px 8px;
  min-width: 0;
  min-height: 82px;
  padding: 9px;
  text-align: left;
  border: 1px solid rgba(126,170,199,.14);
  border-left: 3px solid transparent;
  border-radius: 0;
  clip-path: none;
  background: rgba(7,17,25,.84);
  box-shadow: none;
}
.career-armoury-player:hover { transform: none; filter: brightness(1.12); }
.career-armoury-player.active {
  border-left-color: var(--accent);
  border-color: rgba(82,173,255,.44);
