.career-armoury-player-copy strong,
.career-armoury-player-copy small { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.career-armoury-player-copy strong { color: #f5fbff; font-size: 9px; }
.career-armoury-player-copy small { margin-top: 4px; color: #8ca2b1; font-size: 6.5px; }
.career-armoury-player-rating {
