  grid-template-columns: 34px minmax(150px, 1.6fr) 42px 42px 42px 52px minmax(94px, .7fr) 50px;
  align-items: center;
  gap: 6px;
  min-width: 0;
}
.league-table-head { padding: 7px 9px; color: #728794; font-size: 6px; font-weight: 950; letter-spacing: .12em; border-bottom: 1px solid rgba(255,255,255,.07); }
.league-table-row { min-height: 44px; padding: 7px 9px; border-bottom: 1px solid rgba(255,255,255,.045); color: #b5c3cb; font-size: 7px; }
.league-table-row:last-child { border-bottom: 0; }
.league-table-row.user { border-left: 3px solid #e7c866; background: linear-gradient(90deg, rgba(231,200,102,.12), rgba(231,200,102,.025) 60%, transparent); }
.league-table-row .position { color: #e7c866; font-size: 12px; font-weight: 950; }
.league-table-row .club { min-width: 0; }
.league-table-row .club strong,
.league-table-row .club small { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.league-table-row .club strong { color: #f4f8fa; font-size: 8.5px; }
.league-table-row .club small { margin-top: 3px; color: #738792; font-size: 5.7px; }
.league-table-row .points { color: #fff3b8; font-size: 13px; }
.league-table-row .form { display: flex; gap: 3px; min-width: 0; }
.league-table-row .form span { display: grid; place-items: center; width: 17px; height: 17px; font-size: 5.5px; font-weight: 950; border: 1px solid rgba(255,255,255,.08); }
.league-table-row .form .win { color: #bbffd0; background: rgba(57,170,92,.18); border-color: rgba(77,210,118,.24); }
.league-table-row .form .loss { color: #ffc5bf; background: rgba(178,57,50,.18); border-color: rgba(218,83,74,.24); }
.league-table-row .form .empty { width: auto; border: 0; background: transparent; color: #6f808a; }

.league-detail-grid { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.2fr); gap: 10px; margin-top: 10px; }
.league-opponent-panel,
.league-fixture-panel { padding: 12px; }
.league-opponent-panel > p { color: #9cb0bb; font-size: 8px; line-height: 1.55; }
.league-opponent-facts { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 6px; }
.league-opponent-facts > div { min-width: 0; padding: 9px; border: 1px solid rgba(255,255,255,.055); background: rgba(255,255,255,.025); }
.league-opponent-facts span,
.league-opponent-facts strong { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.league-opponent-facts span { color: #8498a3; font-size: 5.8px; letter-spacing: .12em; }
.league-opponent-facts strong { margin-top: 4px; color: #f5f8f9; font-size: 8px; }
.league-match-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; margin-top: 10px; }
.league-match-actions button { min-height: 40px; }
.league-lock-note { display: block; margin-top: 7px; color: #dc9d78; font-size: 6.5px; }

.league-fixture-list { display: grid; gap: 5px; }
.league-fixture { display: grid; grid-template-columns: 78px minmax(0, 1fr) 84px; align-items: center; gap: 8px; min-width: 0; padding: 8px; border: 1px solid rgba(255,255,255,.045); background: rgba(255,255,255,.018); }
.league-fixture.next { border-color: rgba(231,200,102,.30); background: rgba(231,200,102,.07); }
.league-fixture.played { opacity: .72; }
.league-fixture > span,
.league-fixture > small { color: #8396a1; font-size: 5.8px; font-weight: 900; letter-spacing: .09em; }
.league-fixture > small { text-align: right; }
.league-fixture > div { display: grid; grid-template-columns: minmax(0, 1fr) 50px minmax(0, 1fr); align-items: center; gap: 7px; min-width: 0; }
.league-fixture > div strong { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: #e9f0f3; font-size: 7px; }
.league-fixture > div strong:last-child { text-align: right; }
.league-fixture > div b { text-align: center; color: #fff2b1; font-size: 8px; }

@media (max-width: 980px) {
  .league-intro-panel { grid-template-columns: 1fr; }
