  .league-table-head span:nth-child(5),
  .league-table-row > span:nth-child(5),
  .league-table-head span:nth-child(6),
  .league-table-row > span:nth-child(6),
  .league-table-head span:nth-child(7),
  .league-table-row .form { display: none; }
  .league-table-head span:nth-child(8),
  .league-table-row .points { grid-column: 5; }
  .league-opponent-facts { grid-template-columns: 1fr; }
  .league-match-actions { grid-template-columns: 1fr; }
  .league-fixture { grid-template-columns: 1fr; }
  .league-fixture > div { grid-template-columns: minmax(0, 1fr) 42px minmax(0, 1fr); }
