/* Build 11.16: club identity and matchday scoreboard QoL. */
.scoreboard-team-head > span { min-width: 0; }
.scoreboard-club-name {
  flex: 1 1 auto;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.scoreboard-team-head > span:last-child {
  flex: 0 1 auto;
  max-width: 58%;
  margin-left: 10px;
  font-size: 9px;
  line-height: 1.25;
  text-align: right;
  white-space: normal;
}
.scoreboard-row.selectable {
