  .scoreboard-club-name { white-space: normal; line-height: 1.25; }
  .scoreboard-row.spectating .name b::after { display: none; }
}

/* Build 11.17: training facility, dual progression and future ammunition store. */
.menu-shell[data-menu-route='training'] { --route-accent: #61d6a7; --route-tint: rgba(97,214,167,.10); }
.menu-shell[data-menu-route='store'] { --route-accent: #e19b58; --route-tint: rgba(225,155,88,.09); }

