/* Build 11.19: own-team spectator controls, damage feedback, fast forward and nav affordances. */
.damage-numbers {
  position: absolute;
  inset: 0;
  z-index: 18;
  overflow: hidden;
  pointer-events: none;
}
.damage-number {
  position: absolute;
  display: inline-flex;
  align-items: flex-end;
  gap: 0.34rem;
  min-width: 30px;
  padding: 4px 10px 5px;
  transform: translate(-50%, -50%);
  color: #f7fcff;
  font-size: clamp(14px, 2.2vw, 24px);
  font-weight: 950;
  line-height: 1;
  letter-spacing: .02em;
  text-align: center;
  border: 1px solid rgba(134,215,255,.34);
  border-radius: 999px;
  background: linear-gradient(135deg, rgba(5,18,30,.92), rgba(14,36,62,.72));
  box-shadow: 0 0 0 1px rgba(255,255,255,.04) inset, 0 0 16px rgba(27,103,220,.24);
  will-change: transform, opacity;
}
.damage-number .damage-number-value {
  color: #aee1ff;
  font-size: clamp(15px, 2.3vw, 26px);
  font-weight: 950;
  letter-spacing: .03em;
  text-shadow: 0 2px 4px rgba(0,0,0,.95), 0 0 12px rgba(86,190,255,.72);
}
.damage-number .damage-number-tag {
  color: rgba(226, 240, 255, 0.88);
  font-size: clamp(7px, 0.95vw, 10px);
  font-weight: 900;
  letter-spacing: .18em;
  transform: translateY(-1px);
}
.damage-number.heavy .damage-number-value {
  font-size: clamp(18px, 2.8vw, 30px);
}
.damage-number.incoming {
  border-color: rgba(255,104,104,.4);
  background: linear-gradient(135deg, rgba(52,6,9,.92), rgba(96,18,28,.78));
  box-shadow: 0 0 0 1px rgba(255,255,255,.03) inset, 0 0 16px rgba(255,82,82,.2);
}
.damage-number.incoming .damage-number-value {
  color: #ffb6b6;
  text-shadow: 0 2px 4px rgba(0,0,0,.95), 0 0 12px rgba(255,82,82,.72);
}
.damage-number.critical {
  border-color: rgba(255, 217, 91, .70);
  background: linear-gradient(135deg, rgba(68, 45, 4, .96), rgba(126, 82, 7, .86));
  box-shadow: 0 0 0 1px rgba(255, 250, 190, .07) inset, 0 0 20px rgba(255, 197, 45, .30);
}
.damage-number.critical .damage-number-value {
  color: #ffe36f;
  text-shadow: 0 2px 4px rgba(0,0,0,.95), 0 0 14px rgba(255, 203, 55, .88);
}
.damage-number.critical .damage-number-tag {
  color: rgba(255, 244, 188, .96);
}
.damage-number.incoming.critical {
  border-color: rgba(255, 205, 74, .72);
  background: linear-gradient(135deg, rgba(82, 39, 5, .96), rgba(132, 67, 8, .88));
}
.damage-number.fatal.critical {
  border-color: rgba(255, 235, 130, .84);
  box-shadow: 0 0 0 1px rgba(255, 255, 214, .08) inset, 0 0 26px rgba(255, 194, 35, .42);
}
.damage-number.fatal {
  padding: 5px 11px 6px;
  border-color: rgba(255,219,102,.58);
  background: linear-gradient(135deg, rgba(71, 28, 6, .95), rgba(112, 52, 18, .82));
  box-shadow: 0 0 18px rgba(255,184,66,.22);
}
.damage-number.fatal .damage-number-value {
  color: #fff2b7;
  font-size: clamp(18px, 2.8vw, 30px);
  text-shadow: 0 2px 4px rgba(0,0,0,.95), 0 0 14px rgba(255,205,82,.7);
}
.damage-number.fatal .damage-number-tag {
