.manager-date-copy > small { margin-top: 3px; overflow: hidden; color: #8fbcad; text-overflow: ellipsis; white-space: nowrap; font-size: 5.8px; font-weight: 950; letter-spacing: .09em; }
.menu-subtab-heading { min-width: 0; display: flex !important; align-items: center; justify-content: space-between; gap: 8px; }
.menu-subtab-label { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.menu-subtab-notification { flex: 0 0 auto; display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border: 2px solid #07141e; border-radius: 999px; color: #07141e; background: #f1c65b; box-shadow: 0 0 0 1px rgba(241,198,91,.18), 0 3px 8px rgba(0,0,0,.28); font-size: 7px; font-weight: 950; line-height: 1; letter-spacing: 0; }
.menu-subtab-notification.decision { color: #fff8e7; background: #d97b4f; box-shadow: 0 0 0 1px rgba(217,123,79,.20), 0 3px 8px rgba(0,0,0,.28); }
