/* Build 11.32: live spectator alignment, compact mobile match controls and view-mode polish. */
.view-mode-btn {
  min-width: 132px;
  min-height: 44px;
  padding: 0 12px;
  gap: 10px;
  border-radius: 9px;
  clip-path: none;
  border-color: rgba(104, 204, 229, .42);
  background: linear-gradient(180deg, rgba(17, 58, 76, .94), rgba(7, 27, 39, .98));
  color: #dff8ff;
  box-shadow: inset 0 1px rgba(255,255,255,.08), 0 9px 20px rgba(0,0,0,.26), 0 0 18px rgba(82,173,255,.08);
  text-align: left;
}
.view-mode-btn:active { transform: translateY(1px); }
.view-mode-icon {
  flex: 0 0 auto;
  width: 17px;
  height: 17px;
  border: 0;
}
.view-mode-icon::before,
.view-mode-icon::after {
  width: 7px;
  height: 7px;
  border-width: 2px;
}
.view-mode-icon::before { left: 0; top: 0; }
.view-mode-icon::after { right: 0; bottom: 0; }
.view-mode-copy { min-width: 0; display: grid; gap: 2px; }
.view-mode-copy strong,
.view-mode-copy small { display: block; white-space: nowrap; }
.view-mode-copy strong { color: #f4fbff; font-size: 8px; line-height: 1; letter-spacing: .14em; }
.view-mode-copy small { color: rgba(158, 211, 231, .70); font-size: 5.5px; line-height: 1; letter-spacing: .12em; }

.restore-view-btn:not([hidden]),
body[data-full-view='requested'] .restore-view-btn:not([hidden]) {
  display: inline-grid;
  grid-template-columns: 20px auto;
  align-items: center;
  gap: 7px;
  min-width: 42px;
  min-height: 38px;
  padding: 0 10px;
  border-radius: 9px;
  clip-path: none;
  border: 1px solid rgba(116, 196, 218, .42);
  color: #e5f8ff;
  background: linear-gradient(180deg, rgba(12, 43, 58, .94), rgba(5, 21, 31, .96));
  box-shadow: inset 0 1px rgba(255,255,255,.07), 0 10px 24px rgba(0,0,0,.36);
}
.restore-view-btn svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.restore-view-copy { font-size: 6.5px; font-weight: 950; letter-spacing: .11em; }

/* The live telemetry card follows the camera subject; the accent now visually
   matches the spectator card rather than reading like a separate selection. */
.owned-telemetry {
  border-right-color: var(--blue);
}
.owned-telemetry-head span { color: #7fcfff; }

@media (orientation: portrait) and (max-width: 900px) {
