  body[data-menu-context='pause'] #menuContent { gap: 8px; }
}

@media (orientation: portrait) and (max-width: 430px) {
  .portrait-console-header { min-height: 54px; padding: 7px 8px 7px 11px; }
  .portrait-console-brand strong { font-size: 12px; }
  .portrait-console-brand small { font-size: 5.5px; }
  .view-mode-btn { min-width: 116px; min-height: 40px; padding-inline: 9px; gap: 8px; }
