  body[data-view-mode='maximized'] .match-view .owned-telemetry-grid strong { font-size: 7.4px; }
  .owned-telemetry-foot,
  body[data-view-mode='maximized'] .match-view .owned-telemetry-foot { margin-top: 4px; padding-top: 4px; font-size: 4.5px; }

  .spectator,
  body[data-view-mode='maximized'] .match-view .spectator {
