/* Build 11.33: tactical matchday preparation, decision mail and coordination review. */
.matchday-preparation-panel,
.club-tactics-panel,
.club-role-assignment-panel,
.club-plan-confirm,
.club-mail-decision,
.career-tactical-analysis {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(126, 177, 208, .20);
  background: linear-gradient(145deg, rgba(11, 24, 35, .94), rgba(3, 10, 17, .94));
  box-shadow: inset 0 1px rgba(255,255,255,.045), 0 16px 34px rgba(0,0,0,.20);
}
.matchday-preparation-panel::before,
.club-plan-confirm::before,
.career-tactical-analysis::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  width: 34%;
  height: 2px;
  background: linear-gradient(90deg, var(--accent), transparent);
  pointer-events: none;
}
.matchday-preparation-panel { padding: 15px; }
.matchday-preparation-panel > header {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(210px, .6fr);
  gap: 16px;
  align-items: start;
  padding-bottom: 13px;
  border-bottom: 1px solid rgba(124, 171, 201, .15);
}
.matchday-preparation-panel > header span,
.matchday-preparation-panel > header small,
.matchday-step small,
.club-role-assignment-list small,
.club-plan-confirm small,
.club-mail-decision small,
.career-tactical-metrics small {
  display: block;
  color: var(--muted);
  font-size: 9px;
  line-height: 1.4;
  letter-spacing: .06em;
}
.matchday-preparation-panel > header span,
.matchday-preparation-panel > header aside > span {
  color: var(--accent);
  font-size: 8px;
  font-weight: 950;
  letter-spacing: .18em;
}
.matchday-preparation-panel > header strong { display: block; margin: 5px 0; font-size: 16px; letter-spacing: .06em; }
.matchday-preparation-panel > header aside {
  padding: 10px 12px;
  border-left: 2px solid rgba(82, 173, 255, .56);
  background: rgba(5, 16, 25, .62);
}
.matchday-step-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 7px; margin-top: 12px; }
.matchday-step {
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr);
  gap: 8px;
  align-content: start;
  min-height: 136px;
  padding: 11px;
  border: 1px solid rgba(126, 170, 198, .14);
  background: linear-gradient(180deg, rgba(24, 42, 55, .68), rgba(5, 12, 19, .78));
}
.matchday-step > span {
  color: rgba(148, 186, 211, .58);
  font-size: 9px;
  font-weight: 950;
  letter-spacing: .12em;
}
.matchday-step > div strong { display: block; min-height: 29px; font-size: 10px; letter-spacing: .09em; }
.matchday-step button { grid-column: 1 / -1; align-self: end; min-height: 34px; padding: 0 8px; font-size: 8px; }
.matchday-step.complete { border-color: rgba(84, 215, 177, .32); background: linear-gradient(180deg, rgba(20, 71, 63, .38), rgba(5, 16, 20, .78)); }
.matchday-step.complete > span { color: #62ddbc; }
.matchday-step.locked { opacity: .58; }

.club-plan-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 9px; }
.club-plan-grid > article { padding: 13px; border: 1px solid rgba(126, 170, 198, .15); background: rgba(4, 13, 21, .66); }
.club-plan-grid > article > div:last-child { display: grid; gap: 6px; }
.club-plan-option {
  min-height: 74px;
  padding: 10px 12px;
  text-align: left;
  border-radius: 0;
  border-left: 3px solid rgba(112, 153, 181, .28);
  background: linear-gradient(90deg, rgba(27, 46, 60, .60), rgba(6, 15, 23, .62));
}
.club-plan-option strong,
.club-plan-option small { display: block; }
.club-plan-option strong { font-size: 10px; letter-spacing: .10em; }
.club-plan-option small { margin-top: 5px; color: var(--muted); font-size: 9px; line-height: 1.35; }
.club-plan-option.active { border-left-color: var(--accent); border-color: rgba(244, 185, 66, .42); background: linear-gradient(90deg, rgba(91, 64, 18, .48), rgba(20, 19, 15, .72)); }

.club-tactics-panel,
.club-role-assignment-panel { padding: 15px; }
.club-role-assignment-list { display: grid; gap: 6px; }
.club-role-assignment-list > article {
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr) minmax(155px, .55fr);
  gap: 10px;
  align-items: center;
  min-height: 64px;
  padding: 9px 11px;
  border-left: 2px solid rgba(82, 173, 255, .42);
  background: rgba(4, 13, 21, .58);
}
.club-role-assignment-list > article > span { color: var(--accent); font-size: 10px; font-weight: 950; }
.club-role-assignment-list strong { display: block; font-size: 11px; letter-spacing: .07em; }
.club-role-assignment-list label > span { display: block; margin-bottom: 4px; color: var(--muted); font-size: 7px; font-weight: 900; letter-spacing: .12em; }
.club-role-assignment-list select {
  width: 100%;
  min-height: 36px;
  padding: 0 9px;
  border: 1px solid rgba(116, 174, 211, .30);
  border-radius: 0;
  color: #eef7fd;
  background: #07131d;
  font: 900 9px/1 system-ui, sans-serif;
  letter-spacing: .08em;
}
.club-plan-confirm {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 8px;
  align-items: center;
  padding: 14px 15px;
  border-color: rgba(244, 185, 66, .30);
}
.club-plan-confirm.confirmed { border-color: rgba(84, 215, 177, .38); }
.club-plan-confirm > div > span { display: block; color: var(--accent); font-size: 8px; font-weight: 950; letter-spacing: .18em; }
.club-plan-confirm.confirmed > div > span { color: #62ddbc; }
.club-plan-confirm > div > strong { display: block; margin: 5px 0; font-size: 14px; letter-spacing: .08em; }
.club-plan-confirm button { min-width: 154px; min-height: 42px; padding-inline: 12px; }

.club-mail-decision { margin-top: 14px; padding: 14px; border-color: rgba(244, 185, 66, .34); }
.club-mail-decision > header > span,
.club-mail-decision.resolved > span { color: var(--accent); font-size: 8px; font-weight: 950; letter-spacing: .18em; }
.club-mail-decision > header > strong,
.club-mail-decision.resolved > strong { display: block; margin: 5px 0; font-size: 15px; }
.club-mail-decision > div { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 7px; margin-top: 11px; }
.club-mail-decision > div button { min-height: 70px; padding: 10px 12px; text-align: left; border-radius: 0; }
.club-mail-decision > div button strong,
.club-mail-decision > div button small { display: block; }
.club-mail-decision > div button small { margin-top: 5px; }
.club-mail-decision.resolved { border-color: rgba(84, 215, 177, .34); }
.club-mail-decision.resolved > span { color: #62ddbc; }

.career-tactical-analysis { margin-top: 12px; padding: 15px; }
.career-tactical-plan-summary { display: flex; flex-wrap: wrap; gap: 6px; margin: 11px 0; }
.career-tactical-plan-summary span { padding: 5px 8px; border-left: 2px solid var(--accent); background: rgba(244, 185, 66, .08); font-size: 8px; font-weight: 900; letter-spacing: .10em; }
.career-tactical-metrics { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 1px; padding: 1px; background: rgba(124, 171, 201, .16); }
.career-tactical-metrics article { min-height: 92px; padding: 11px; background: linear-gradient(180deg, rgba(18, 32, 43, .96), rgba(5, 12, 19, .96)); }
.career-tactical-metrics span { display: block; color: #8fabc0; font-size: 7px; font-weight: 950; letter-spacing: .13em; }
.career-tactical-metrics strong { display: block; margin: 7px 0 4px; color: #f2f7fb; font-size: 20px; }
.career-tactical-recommendations { display: grid; gap: 5px; margin-top: 10px; }
.career-tactical-recommendations article { display: grid; grid-template-columns: 28px 1fr; gap: 9px; align-items: center; padding: 9px 10px; border-left: 2px solid rgba(82, 173, 255, .42); background: rgba(4, 13, 21, .58); }
.career-tactical-recommendations span { color: var(--accent); font-size: 8px; font-weight: 950; }
.career-tactical-recommendations p { margin: 0; color: #cfdae4; font-size: 10px; line-height: 1.4; }

@media (max-width: 920px) {
  .matchday-step-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .club-plan-grid { grid-template-columns: 1fr; }
  .career-tactical-metrics { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: 620px) {
  .matchday-preparation-panel > header { grid-template-columns: 1fr; }
  .matchday-step-grid { grid-template-columns: 1fr; }
  .matchday-step { min-height: 0; grid-template-columns: 24px minmax(0, 1fr) auto; align-items: center; }
  .matchday-step button { grid-column: auto; min-width: 96px; }
  .club-role-assignment-list > article { grid-template-columns: 24px minmax(0, 1fr); }
  .club-role-assignment-list label { grid-column: 2; }
  .club-plan-confirm { grid-template-columns: 1fr 1fr; }
  .club-plan-confirm > div { grid-column: 1 / -1; }
  .club-plan-confirm button { min-width: 0; }
  .club-mail-decision > div { grid-template-columns: 1fr; }
  .career-tactical-metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (orientation: landscape) and (max-height: 520px) {
  .matchday-preparation-panel { padding: 10px; }
  .matchday-preparation-panel > header { grid-template-columns: minmax(0, 1.4fr) minmax(180px, .6fr); padding-bottom: 8px; }
