/* Build 11.43: sponsor identity remains legible in portrait and active partners receive a short between-round broadcast bumper. */
.sponsor-bug > span:first-child {
  display: block;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.sponsor-round-transition {
  --sponsor-colour: #75c6ff;
  position: absolute;
  inset: 0;
  z-index: 32;
  display: grid;
  place-items: center;
  overflow: hidden;
  padding: max(18px, env(safe-area-inset-top)) max(18px, env(safe-area-inset-right)) max(18px, env(safe-area-inset-bottom)) max(18px, env(safe-area-inset-left));
  color: var(--sponsor-colour);
  background:
    linear-gradient(115deg, rgba(2,7,12,.97), rgba(7,17,25,.92) 48%, rgba(2,6,10,.98)),
    repeating-linear-gradient(90deg, transparent 0 54px, rgba(255,255,255,.02) 55px);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity .16s ease, visibility .16s ease;
}
.sponsor-round-transition[hidden] { display: none !important; }
.sponsor-round-transition::before,
.sponsor-round-transition::after {
  content: '';
  position: absolute;
  pointer-events: none;
}
.sponsor-round-transition::before {
  inset: -30%;
  background: linear-gradient(110deg, transparent 34%, color-mix(in srgb, var(--sponsor-colour) 12%, transparent) 48%, transparent 62%);
  transform: translateX(-34%);
}
.sponsor-round-transition::after {
  left: 7%;
  right: 7%;
  top: 50%;
  height: 1px;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--sponsor-colour) 62%, transparent), transparent);
  box-shadow: 0 -72px color-mix(in srgb, var(--sponsor-colour) 10%, transparent), 0 72px color-mix(in srgb, var(--sponsor-colour) 10%, transparent);
}
.sponsor-round-transition.show {
  opacity: 1;
  visibility: visible;
}
.sponsor-round-transition.show::before { animation: sponsorRoundSweep 2.10s ease-out both; }
.sponsor-round-transition.aegis { --sponsor-colour: #75c6ff; }
.sponsor-round-transition.voltrush { --sponsor-colour: #f7d54a; }
.sponsor-round-transition.northstar { --sponsor-colour: #c8ddff; }
.sponsor-round-transition.redline { --sponsor-colour: #ff7670; }
.sponsor-round-transition.ironclad { --sponsor-colour: #d69a5f; }
.sponsor-round-transition-frame {
  position: relative;
  z-index: 1;
  width: min(520px, 88vw);
  display: grid;
  justify-items: center;
  gap: 9px;
  padding: 22px 24px;
