/* Build 11.48: premium debrief overlay and portrait management consistency. */
.team-note-overlay[hidden] { display: none !important; }
.team-note-overlay {
  overflow-y: auto;
  overscroll-behavior: contain;
  animation: teamNoteBackdropIn .18s ease-out both;
}
.team-note-dialog {
  isolation: isolate;
  max-height: min(78vh, 660px);
  overflow: auto;
  border-color: rgba(116, 180, 214, .38);
  border-top: 3px solid #72cdfc;
  background:
    linear-gradient(135deg, rgba(31, 72, 96, .22), transparent 42%),
    linear-gradient(160deg, rgba(16, 31, 43, .99), rgba(4, 11, 17, .99));
  box-shadow: 0 28px 72px rgba(0, 0, 0, .58), inset 0 1px rgba(255, 255, 255, .06);
  animation: teamNoteDialogIn .22s cubic-bezier(.2, .8, .25, 1) both;
}
.team-note-dialog::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background:
    repeating-linear-gradient(90deg, transparent 0 27px, rgba(114, 205, 252, .025) 28px),
    linear-gradient(180deg, rgba(255,255,255,.025), transparent 34%);
}
.team-note-quote {
  position: absolute;
  top: 10px;
  right: 57px;
  color: rgba(114, 205, 252, .12);
  font-family: Georgia, serif;
  font-size: 76px;
  line-height: .8;
  pointer-events: none;
}
.team-note-close {
  z-index: 2;
  border-color: rgba(114, 205, 252, .38);
  box-shadow: 0 0 0 1px rgba(114, 205, 252, .06), 0 8px 22px rgba(0,0,0,.28);
}
.team-note-close:hover,
.team-note-close:focus-visible {
  color: #fff;
  border-color: rgba(160, 224, 255, .78);
  background: rgba(32, 88, 119, .84);
}
.team-note-kicker { color: #85d9ff; }
.team-note-body {
  position: relative;
  margin-top: 16px;
  padding: 14px 14px 14px 17px;
  border-left: 3px solid #72cdfc;
  background: rgba(2, 9, 14, .58);
  color: #edf6fb;
  font-size: 13px;
  line-height: 1.72;
}
.team-note-footer {
  padding: 10px 11px;
  border: 1px solid rgba(242, 185, 98, .22);
  background: rgba(83, 55, 17, .18);
  line-height: 1.45;
