.team-note-overlay[data-tone='personal'] .team-note-dialog { border-top-color: #72cdfc; }
.team-note-overlay[data-tone='insight'] .team-note-dialog,
.team-note-overlay[data-tone='debrief'] .team-note-dialog { border-top-color: #f0bd68; }
.team-note-overlay[data-tone='insight'] .team-note-body,
.team-note-overlay[data-tone='debrief'] .team-note-body { border-left-color: #f0bd68; }
.team-note-overlay[data-tone='insight'] .team-note-kicker,
.team-note-overlay[data-tone='debrief'] .team-note-kicker { color: #f0bd68; }
.team-expand-card {
  position: relative;
  padding-right: 38px;
  overflow: hidden;
  transition: border-color .15s ease, background .15s ease, transform .15s ease;
}
.team-expand-card::after {
  content: '↗';
  position: absolute;
  top: 9px;
  right: 10px;
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border: 1px solid rgba(120, 203, 246, .22);
  border-radius: 999px;
  color: #85d9ff;
  background: rgba(7, 23, 34, .78);
