.team-expand-card:hover,
.team-expand-card:focus-visible {
  transform: translateY(-1px);
  border-left-color: #85d9ff;
  background: rgba(35, 77, 101, .28);
}
.team-expand-card.insight::after,
.team-debrief-note::after { color: #f0bd68; border-color: rgba(240, 189, 104, .25); }
@keyframes teamNoteBackdropIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes teamNoteDialogIn { from { opacity: 0; transform: translateY(12px) scale(.985); } to { opacity: 1; transform: translateY(0) scale(1); } }

