/* Build 11.59: iOS post-report training-route viewport recovery. */
@media (orientation: portrait) and (max-width: 900px) {
  html,
  body {
    min-height: 100%;
    height: 100%;
  }

  /* #app already uses position:fixed and inset:0. Explicit 100dvh heights can
     become stale after dismissing a focused modal in iOS Safari, leaving a
     black strip beneath Command HQ. Let the fixed insets own the height. */
  #app {
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    width: auto;
    height: auto;
    min-height: 0;
    max-height: none;
  }

  body[data-app-state='menu'] .menu-shell {
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    width: auto;
    height: auto;
    min-height: 0;
    max-height: none;
  }

  body[data-app-state='menu'] .menu-layout {
    align-self: stretch;
    flex: 1 1 auto;
    height: auto;
    min-height: 0;
  }

  body[data-app-state='menu'] .menu-content {
    flex: 1 1 0;
    height: auto;
    min-height: 0;
    overscroll-behavior-y: contain;
    -webkit-overflow-scrolling: touch;
  }
}

/* Build 11.60: landscape minimap controls and portrait rotation gate. */
.landscape-rotation-gate {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: grid;
  place-items: center;
  padding:
    max(24px, env(safe-area-inset-top))
    max(22px, env(safe-area-inset-right))
    max(24px, env(safe-area-inset-bottom))
    max(22px, env(safe-area-inset-left));
  color: #eef7fb;
  background: #020508;
  text-align: center;
  overscroll-behavior: none;
  touch-action: manipulation;
}
.landscape-rotation-gate[hidden] { display: none !important; }
