  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(0 0 14px rgba(105,200,246,.25));
  animation: landscape-rotate-prompt 1.8s ease-in-out infinite;
}
.landscape-rotation-gate-card > span {
  color: #69c8f6;
