  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: 16px;
  padding: 18px;
  border: 1px solid rgba(96, 158, 187, .20);
  border-left: 4px solid var(--route-accent, #68cdb6);
  background: linear-gradient(145deg, rgba(12, 38, 52, .94), rgba(4, 13, 20, .98));
}
.section-hub-hero span { color: var(--route-accent, #68cdb6); font-size: 7px; font-weight: 950; letter-spacing: .17em; }
.section-hub-hero h2 { margin: 7px 0 5px; color: #f4f8fa; font-size: clamp(22px, 4vw, 36px); line-height: .95; letter-spacing: .025em; }
.section-hub-hero p { max-width: 650px; margin: 0; color: #8ca2ad; font-size: 8px; line-height: 1.5; }
.section-hub-hero > button { min-height: 44px; padding: 8px 12px; }
.section-hub-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 7px;
  margin-top: 8px;
}
.section-hub-metrics article {
  min-width: 0;
  padding: 11px;
  border: 1px solid rgba(99, 153, 181, .16);
  background: rgba(7, 23, 32, .82);
}
.section-hub-metrics span,
.section-hub-metrics strong,
.section-hub-metrics small { display: block; }
.section-hub-metrics span { color: #7893a1; font-size: 6px; font-weight: 950; letter-spacing: .12em; }
.section-hub-metrics strong { margin-top: 7px; overflow-wrap: anywhere; color: #f0f6f8; font-size: 17px; }
.section-hub-metrics small { margin-top: 4px; color: #68818e; font-size: 5.7px; font-weight: 850; }
.section-hub-pages {
  margin-top: 10px;
  padding: 13px;
  border: 1px solid rgba(94, 150, 181, .18);
  background: rgba(5, 18, 26, .88);
}
.section-hub-pages > div:last-child { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 6px; }
.section-hub-route {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto 16px;
  align-items: center;
  gap: 9px;
  min-height: 58px;
  padding: 9px 10px;
  text-align: left;
  border: 1px solid rgba(101, 157, 187, .15);
  background: rgba(12, 32, 43, .72);
}
.section-hub-route:hover,
.section-hub-route:focus-visible { border-color: rgba(104, 205, 182, .44); background: rgba(18, 51, 63, .90); }
.section-hub-route > span { min-width: 0; }
.section-hub-route strong { display: block; color: #e4eef2; font-size: 8px; letter-spacing: .09em; }
.section-hub-route small { display: block; margin-top: 3px; color: #77909c; font-size: 6px; line-height: 1.3; }
.section-hub-route em { display: block; margin-top: 4px; color: #d6a17d; font-size: 5.6px; font-style: normal; }
.section-hub-route > b { color: #e5c766; font-size: 6px; letter-spacing: .07em; text-align: right; }
.section-hub-route > i { color: #75ceb8; font-size: 17px; font-style: normal; }
.section-hub-route.attention { border-left: 3px solid #d99a5d; }
.section-hub-route:disabled { opacity: .52; cursor: not-allowed; }
.section-hub-recent {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  margin-top: 8px;
  padding: 9px;
  border: 1px solid rgba(92, 153, 181, .13);
  background: rgba(7, 22, 31, .72);
}
.section-hub-recent > span { color: #718b98; font-size: 6px; font-weight: 950; letter-spacing: .12em; }
.section-hub-recent > div { display: flex; gap: 5px; min-width: 0; overflow-x: auto; scrollbar-width: none; }
.section-hub-recent > div::-webkit-scrollbar { display: none; }
.section-hub-recent button { flex: 0 0 auto; min-height: 36px; padding: 6px 9px; border: 1px solid rgba(101, 157, 187, .18); background: rgba(15, 40, 52, .70); color: #c7d9e1; font-size: 6px; font-weight: 900; }

.command-directory-search {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: end;
  gap: 7px;
  margin-bottom: 9px;
  padding: 9px;
  border: 1px solid rgba(104, 205, 182, .16);
  background: rgba(10, 31, 41, .76);
}
.command-directory-search label { min-width: 0; }
.command-directory-search label > span { display: block; margin-bottom: 5px; color: #79cdb9; font-size: 6px; font-weight: 950; letter-spacing: .13em; }
.command-directory-search input {
  width: 100%;
  min-height: 44px;
  padding: 9px 11px;
  border: 1px solid rgba(111, 171, 201, .28);
  background: rgba(3, 13, 20, .90);
  color: #edf7fa;
  font-size: 9px;
}
.command-directory-search input::placeholder { color: #607986; }
.command-directory-search button { min-height: 44px; padding: 8px 10px; }
.command-directory-search > strong { align-self: center; color: #7f98a4; font-size: 6px; letter-spacing: .08em; white-space: nowrap; }
.command-directory-recommended,
.command-directory-recent {
  margin-bottom: 9px;
  padding: 9px;
  border: 1px solid rgba(104, 158, 188, .16);
  background: rgba(6, 21, 30, .76);
}
.command-directory-recommended > span,
.command-directory-recent > span { display: block; margin-bottom: 6px; color: #e1bf59; font-size: 6px; font-weight: 950; letter-spacing: .14em; }
.command-directory-recommended > div { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 5px; }
.command-directory-recommended button {
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  min-height: 58px;
  padding: 8px;
  text-align: left;
  border: 1px solid rgba(226, 190, 83, .17);
  background: rgba(52, 42, 14, .28);
}
.command-directory-recommended button > b { color: #e5c55f; font-size: 8px; }
.command-directory-recommended button span { min-width: 0; }
.command-directory-recommended button strong { display: block; color: #f2f5f6; font-size: 7px; }
.command-directory-recommended button small { display: block; margin-top: 3px; color: #8297a0; font-size: 5.7px; line-height: 1.3; }
.command-directory-recommended button em { color: #77cdb8; font-size: 5.5px; font-style: normal; }
.command-directory-recent > div { display: flex; gap: 5px; overflow-x: auto; scrollbar-width: none; }
.command-directory-recent > div::-webkit-scrollbar { display: none; }
.command-directory-recent button { flex: 0 0 auto; min-height: 42px; padding: 7px 10px; text-align: left; border: 1px solid rgba(101, 157, 187, .16); background: rgba(13, 35, 47, .68); }
.command-directory-recent strong,
.command-directory-recent small { display: block; }
.command-directory-recent strong { color: #dce8ed; font-size: 6.5px; }
.command-directory-recent small { margin-top: 3px; color: #6d8794; font-size: 5.2px; }
.command-directory-route i { display: block; margin-top: 4px; color: #c69372; font-size: 5.5px; font-style: normal; line-height: 1.25; }
.command-directory-route.attention { border-left: 2px solid #c98b58; }
.command-directory-route.context { border-left: 2px dashed #7299aa; }
.command-directory-route:disabled { opacity: .48; cursor: not-allowed; }
.command-directory-group[hidden],
.command-directory-route[hidden] { display: none !important; }
.command-directory-empty { padding: 18px; text-align: center; border: 1px dashed rgba(101, 157, 187, .22); color: #78909c; }
.command-directory-empty strong { display: block; color: #dce8ed; font-size: 9px; }
.command-directory-empty p { margin: 6px 0 0; font-size: 7px; }
.command-directory-empty[hidden] { display: none !important; }

@media (max-width: 760px) {
  .menu-route-locator { min-height: 46px; padding: 6px 9px; }
  body[data-menu-context='main'] .menu-subnav-shell { top: 46px; }
  body[data-menu-context='pause'] .menu-route-locator { top: 44px; }
  body[data-menu-context='pause'] .menu-subnav-shell { top: 90px; }
  .menu-route-context > span { display: none; }
  .menu-route-path button { min-height: 34px; }
  .menu-subnav-shell .menu-subnav { align-items: stretch; }
  .menu-subtab { min-width: max-content; padding-inline: 11px; }
  .menu-subtab small { display: none; }
  .section-hub-metrics { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .section-hub-pages > div:last-child,
