  .menu-route-path { gap: 5px; }
  .menu-route-path button { padding-inline: 7px; font-size: 6.4px; }
  .menu-route-path > strong { font-size: 7.5px; letter-spacing: .075em; }
  .menu-route-context > b { max-width: 105px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 5.5px; }
  .menu-tab-badge { top: 2px; right: 2px; min-width: 15px; height: 15px; font-size: 5.3px; }
  .section-hub-hero { grid-template-columns: 1fr; align-items: start; padding: 13px; }
  .section-hub-hero > button { width: 100%; }
  .section-hub-metrics article { padding: 9px; }
  .section-hub-metrics strong { font-size: 14px; }
  .section-hub-pages { padding: 9px; }
  .section-hub-route { min-height: 64px; grid-template-columns: minmax(0,1fr) auto 12px; padding: 8px; }
  .section-hub-route > b { max-width: 84px; white-space: normal; }
  .section-hub-recent { grid-template-columns: 1fr; }
  .command-directory-search { grid-template-columns: minmax(0,1fr) auto; }
  .command-directory-search > strong { grid-column: 1 / -1; }
  .command-directory-recommended button { grid-template-columns: 22px minmax(0,1fr); }
  .command-directory-recommended button em { grid-column: 2; }
}
@media (orientation: portrait) and (max-width: 350px) {
  .menu-route-context { display: none; }
  .menu-route-locator { grid-template-columns: 1fr; }
  .menu-tab-badge { transform: scale(.88); transform-origin: top right; }
  .section-hub-metrics { grid-template-columns: 1fr 1fr; }
}

@media (orientation: portrait) and (max-width: 430px) {
  .menu-tab { min-height: 44px !important; }
  .menu-route-locator { min-height: 50px; }
  .menu-route-path button { min-height: 44px; }
  body[data-menu-context='main'] .menu-subnav-shell { top: 50px; }
  body[data-menu-context='pause'] .menu-subnav-shell { top: 94px; }
}


/* Build 11.75: performance, navigation and match clarity. */
.menu-route-locator { display: none !important; }
body[data-menu-context='main'] .menu-subnav-shell { top: 0; }
body[data-menu-context='pause'] .menu-subnav-shell { top: 44px; }
.tactical-range-warning {
  grid-column: 1 / -1;
  display: grid;
  gap: 4px;
  margin: 9px 0 0;
  padding: 11px 12px;
  border: 1px solid rgba(234, 155, 82, .38);
  border-left: 3px solid #e49b55;
  background: linear-gradient(135deg, rgba(77, 43, 17, .48), rgba(26, 18, 12, .72));
}
.tactical-range-warning.danger { border-color: rgba(239, 107, 82, .46); border-left-color: #ef6b52; background: linear-gradient(135deg, rgba(80, 27, 20, .52), rgba(27, 14, 13, .76)); }
.tactical-range-warning span,
.tactical-range-warning strong,
.tactical-range-warning small { display: block; }
.tactical-range-warning span { color: #ffc487; font-size: 7px; font-weight: 950; letter-spacing: .15em; }
.tactical-range-warning.danger span { color: #ff9e8c; }
.tactical-range-warning strong { color: #f5f2ec; font-size: 9px; letter-spacing: .08em; }
