/* Build 11.76: reversible stat allocation, single fixed End Day control and focused blockers. */
.manager-topbar-actions { grid-template-columns: repeat(3, 52px); }
.manager-end-day-slot {
  display: grid;
  min-width: 0;
  padding: 0 max(54px, calc(44px + 10px)) 0 0;
  background: transparent;
}
.manager-end-day-primary {
  position: relative;
  min-width: 0;
  min-height: 54px;
  display: grid;
  align-content: center;
  justify-items: end;
  gap: 3px;
  padding: 6px 10px;
  border: 1px solid rgba(100, 205, 172, .30);
  border-radius: 9px;
  color: #f5fbf9;
  background: linear-gradient(180deg, rgba(22, 70, 63, .76), rgba(8, 30, 31, .92));
  box-shadow: inset 0 -2px rgba(93, 220, 177, .20);
  text-align: right;
}
.manager-end-day-primary > span:first-child {
  color: #88bdae;
  font-size: 6px;
  font-weight: 950;
  letter-spacing: .13em;
}
.manager-end-day-primary > strong {
  color: #f6fffb;
  font-size: 11px;
  line-height: 1;
  letter-spacing: .10em;
}
.manager-end-day-primary > small {
  max-width: 100%;
  overflow: hidden;
  color: #a8c9c0;
  font-size: 6px;
  font-weight: 850;
  line-height: 1.15;
  letter-spacing: .06em;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.manager-end-day-primary:hover,
.manager-end-day-primary:focus-visible { border-color: rgba(116, 235, 194, .70); background: linear-gradient(180deg, rgba(29, 91, 78, .90), rgba(9, 38, 36, .96)); }
.manager-end-day-primary.matchday { border-color: rgba(244, 191, 73, .60); box-shadow: inset 0 -2px rgba(244, 191, 73, .34); }
.manager-end-day-primary.blocked {
  border-color: rgba(242, 103, 84, .66);
  background: linear-gradient(180deg, rgba(89, 35, 31, .88), rgba(37, 17, 20, .96));
  box-shadow: inset 0 -2px rgba(242, 103, 84, .32);
}
.manager-end-day-primary:disabled { opacity: .48; }
.manager-end-day-primary .manager-end-day-block-badge { top: 4px; right: 4px; }
.club-calendar-strip { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.club-end-day-inline { display: none !important; }

.player-stat-point-banner {
  display: grid;
  margin: 8px 0 10px;
  padding: 10px 11px;
  border: 1px solid rgba(244, 191, 73, .44);
  border-left: 3px solid #f0bd4f;
  background: linear-gradient(100deg, rgba(91, 67, 17, .52), rgba(17, 27, 31, .78));
}
.player-stat-point-banner.pending { border-color: rgba(91, 213, 174, .48); border-left-color: #61d5ae; background: linear-gradient(100deg, rgba(18, 78, 66, .48), rgba(13, 26, 31, .82)); }
.player-stat-point-banner span,
.player-stat-point-banner strong,
.player-stat-point-banner small { display: block; }
.player-stat-point-banner span { color: #f4ca68; font-size: 7px; font-weight: 950; letter-spacing: .13em; }
.player-stat-point-banner.pending span { color: #86e2c5; }
.player-stat-point-banner strong { margin-top: 4px; color: #fff7da; font-size: 11px; letter-spacing: .05em; }
.player-stat-point-banner small { margin-top: 4px; color: #c4b78f; font-size: 7px; line-height: 1.4; }
.player-stat-point-banner.pending small { color: #a9cfc3; }

.team-attribute-row { grid-template-columns: minmax(125px, 1.25fr) minmax(72px, 1fr) 34px minmax(66px, auto); }
.team-attribute-row > em { display: inline-flex; align-items: baseline; justify-content: flex-end; gap: 2px; }
.team-attribute-row > em small { color: #70deb9; font-size: 6px; font-style: normal; }
.team-attribute-row.pending-change { background: linear-gradient(90deg, rgba(59, 185, 143, .08), transparent); }
.team-attribute-row.pending-change > i > b { background: linear-gradient(90deg, #2f8f73, #6be1ba); }
.team-attribute-stepper { display: grid; grid-template-columns: repeat(2, 32px); gap: 3px; }
.team-attribute-stepper button { min-width: 32px; min-height: 32px; padding: 0; font-size: 14px; }
.team-attribute-stepper button:first-child:not(:disabled) { color: #ffc0a7; border-color: rgba(236, 119, 83, .36); }
.team-attribute-stepper button:last-child:not(:disabled) { color: #a8f0d7; border-color: rgba(82, 211, 169, .38); }
.player-stat-allocation-actions {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 6px;
  margin-top: 10px;
  padding-top: 10px;
  border-top: 1px solid rgba(126, 178, 198, .16);
}
.player-stat-allocation-actions > span { color: #8ca5b2; font-size: 7px; font-weight: 900; letter-spacing: .06em; }
.player-stat-allocation-actions button { min-height: 38px; }

@media (orientation: portrait) and (max-width: 430px) {
  .manager-topbar-actions { grid-template-columns: repeat(3, 44px); }
  .manager-end-day-slot { padding-right: 50px; }
  .manager-end-day-primary { min-height: 54px; padding: 5px 7px; border-radius: 7px; }
  .manager-end-day-primary > span:first-child { display: none; }
  .manager-end-day-primary > strong { font-size: 8.5px; letter-spacing: .055em; }
  .manager-end-day-primary > small { font-size: 5.5px; }
  .club-calendar-strip { grid-template-columns: 1fr; }
  .team-attribute-row { grid-template-columns: minmax(100px, 1fr) minmax(50px, .62fr) 30px 66px; gap: 5px; }
  .player-stat-allocation-actions { grid-template-columns: 1fr 1fr; }
  .player-stat-allocation-actions > span { grid-column: 1 / -1; }
  .player-stat-allocation-actions button { min-height: 44px; }
}
@media (orientation: portrait) and (max-width: 360px) {
  .manager-end-day-primary > small { display: none; }
  .manager-end-day-primary > strong { font-size: 8px; }
  .team-attribute-row { grid-template-columns: minmax(88px, 1fr) minmax(40px, .55fr) 28px 62px; }
  .team-attribute-stepper { grid-template-columns: repeat(2, 29px); }
  .team-attribute-stepper button { min-width: 29px; min-height: 32px; }
}


/* Build 11.77: exact action routing, reversible management drafts and grouped End Day blockers. */
.workflow-save-bar {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  margin: 0 0 10px;
  padding: 13px 14px;
  border: 1px solid rgba(112, 164, 194, .28);
  border-left: 3px solid rgba(86, 184, 230, .72);
  background: linear-gradient(135deg, rgba(8, 27, 39, .96), rgba(5, 15, 23, .94));
}
.workflow-save-bar.dirty { border-color: rgba(245, 187, 73, .46); border-left-color: var(--accent); background: linear-gradient(135deg, rgba(50, 39, 13, .80), rgba(8, 18, 24, .96)); }
.workflow-save-bar > div:first-child { min-width: 0; }
.workflow-save-bar span, .workflow-save-bar strong, .workflow-save-bar small { display: block; }
.workflow-save-bar span { color: var(--accent); font-size: 8px; font-weight: 950; letter-spacing: .16em; }
.workflow-save-bar strong { margin-top: 4px; color: #f5f8fa; font-size: 15px; letter-spacing: .07em; }
.workflow-save-bar small { margin-top: 4px; color: #98acb9; font-size: 9px; line-height: 1.45; }
.workflow-save-bar > div:last-child { display: flex; gap: 7px; }
.workflow-save-bar button { min-height: 44px; min-width: 126px; padding: 0 13px; }
.workflow-save-bar button:disabled { opacity: .38; }

.management-arrival-banner {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  margin: 0 0 10px;
  padding: 14px;
  border: 1px solid rgba(91, 194, 237, .42);
  border-left: 4px solid #59c4ed;
  background: linear-gradient(135deg, rgba(8, 45, 62, .94), rgba(5, 17, 25, .97));
  box-shadow: 0 12px 30px rgba(0, 0, 0, .22);
}
.management-arrival-banner.blocking, .management-arrival-banner.urgent { border-color: rgba(239, 90, 83, .54); border-left-color: #ef5a53; background: linear-gradient(135deg, rgba(58, 18, 18, .92), rgba(8, 17, 23, .97)); }
.management-arrival-banner.important { border-left-color: var(--accent); }
.management-arrival-banner.resolved { border-color: rgba(76, 201, 147, .42); border-left-color: #4cc993; }
.management-arrival-banner span, .management-arrival-banner strong, .management-arrival-banner small { display: block; }
.management-arrival-banner span { color: #90d9f6; font-size: 8px; font-weight: 950; letter-spacing: .16em; }
.management-arrival-banner strong { margin-top: 5px; color: #fff; font-size: 16px; letter-spacing: .055em; }
.management-arrival-banner small { margin-top: 5px; max-width: 72ch; color: #a9bac4; font-size: 9px; line-height: 1.5; }
.management-arrival-banner > div:last-child { display: flex; gap: 7px; }
.management-arrival-banner button { min-height: 44px; }
.management-arrival-target { animation: managementArrivalPulse 1.65s ease-out 1; outline: 2px solid rgba(245, 187, 73, .78); outline-offset: 3px; }
@keyframes managementArrivalPulse { 0%, 55% { box-shadow: 0 0 0 0 rgba(245, 187, 73, .44); } 100% { box-shadow: 0 0 0 18px rgba(245, 187, 73, 0); } }

.club-must-respond-strip .club-response-groups { display: grid; gap: 8px; }
.club-response-group { border: 1px solid rgba(239, 90, 83, .20); background: rgba(10, 14, 19, .46); }
.club-response-group > header { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 8px 10px; border-bottom: 1px solid rgba(239, 90, 83, .16); }
.club-response-group > header span { color: #f5a09b; font-size: 7px; font-weight: 950; letter-spacing: .16em; }
.club-response-group > header strong { min-width: 24px; height: 24px; display: grid; place-items: center; border: 1px solid rgba(239, 90, 83, .42); color: #fff; font-size: 9px; }
.club-response-group > div { display: grid; gap: 1px; }
