/* Build 11.91: brighter spectator feed, phone-width safety and supporter culture. */
body[data-app-state='match'][data-view-mode='windowed'] .match-view::before {
  inset: auto !important;
  top: auto !important;
  right: auto !important;
  width: auto !important;
  height: auto !important;
  background: none !important;
  text-shadow: 0 1px 2px #000;
}
body[data-app-state='match'][data-view-mode='windowed'] .match-view::after { opacity: .035 !important; }
body[data-app-state='match'][data-view-mode='windowed'] .match-view canvas { filter: saturate(1.07) contrast(1.025) brightness(1.09); }

.career-report-actions { grid-template-columns: minmax(0,1fr) minmax(280px,auto); gap: 12px; }
.career-report-action-buttons { display: grid; grid-template-columns: minmax(130px,.72fr) minmax(170px,1fr); gap: 8px; }
.career-report-action-buttons > button { width: 100%; min-height: 42px; }

.supporter-metric-grid { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:8px; margin:10px 0; }
.supporter-metric-grid article { min-width:0; padding:13px; border:1px solid rgba(99,210,174,.18); background:linear-gradient(150deg,rgba(12,39,42,.80),rgba(5,15,21,.96)); }
.supporter-metric-grid span,.supporter-season-card span,.supporter-reaction-card article>span,.supporter-principles>span { color:#72d6bb; font-size:6.5px; font-weight:950; letter-spacing:.14em; }
.supporter-metric-grid strong { display:block; margin-top:7px; color:#f3f7f5; font-size:20px; }
.supporter-metric-grid small { display:block; margin-top:5px; color:rgba(196,219,214,.60); font-size:5.5px; }
.supporter-season-card { padding:15px; border:1px solid rgba(241,199,79,.24); background:linear-gradient(135deg,rgba(64,48,12,.30),rgba(6,17,23,.96)); }
.supporter-season-card header { display:grid; grid-template-columns:minmax(0,1fr) auto; gap:16px; align-items:start; }
.supporter-season-card header strong { display:block; margin-top:5px; color:#f8dd82; font-size:18px; }
.supporter-season-card header small { display:block; margin-top:4px; color:#d6e0de; font-size:7px; }
.supporter-season-card header aside { min-width:130px; text-align:right; }
.supporter-season-card header aside strong { font-size:26px; color:#fff; }
.supporter-season-card>p { color:rgba(211,225,222,.72); font-size:7.5px; line-height:1.55; }
.supporter-expectation-track { position:relative; display:flex; justify-content:space-between; margin-top:12px; padding-top:14px; color:#78929b; font-size:6px; }
.supporter-expectation-track::before { content:''; position:absolute; top:5px; left:0; right:0; height:4px; background:rgba(255,255,255,.08); }
.supporter-expectation-track i::before,.supporter-expectation-track i::after { content:''; position:absolute; top:1px; width:3px; height:12px; }
.supporter-expectation-track i::before { left:var(--expected); background:#f0c85d; }
.supporter-expectation-track i::after { left:var(--current); background:#63d2ae; box-shadow:0 0 8px rgba(99,210,174,.45); }
.supporter-detail-grid { display:grid; grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr); gap:10px; margin-top:10px; }
.supporter-history-card,.supporter-reaction-card { min-width:0; padding:13px; border:1px solid rgba(104,158,188,.18); background:rgba(5,15,22,.88); }
.supporter-history-bars { min-height:170px; display:flex; align-items:end; gap:5px; padding:16px 2px 0; }
.supporter-history-bars>i { flex:1 1 0; min-width:5px; max-width:24px; position:relative; display:flex; align-items:end; background:rgba(99,210,174,.10); }
.supporter-history-bars>i b { display:block; width:100%; height:100%; background:linear-gradient(180deg,#73d9bd,#245d5a); }
.supporter-history-bars>i span { position:absolute; left:50%; top:100%; transform:translateX(-50%); margin-top:5px; color:#718a94; font-size:5px; }
.supporter-history-bars>p,.supporter-empty { color:#708792; font-size:7px; line-height:1.5; }
.supporter-reaction-card>div>article { padding:10px 0; border-top:1px solid rgba(255,255,255,.06); }
.supporter-reaction-card article strong { display:block; margin-top:4px; color:#eef5f3; font-size:9px; }
.supporter-reaction-card article p { margin:5px 0; color:#9fb4b8; font-size:7px; line-height:1.45; }
.supporter-reaction-card article small { color:#d2b85b; font-size:5.7px; font-weight:900; }
.supporter-reaction-card article.positive { border-left:2px solid #63d2ae; padding-left:8px; }
.supporter-reaction-card article.warning { border-left:2px solid #dfac55; padding-left:8px; }
.supporter-principles { display:grid; grid-template-columns:auto minmax(0,1fr); gap:12px; margin-top:10px; padding:10px 12px; border:1px solid rgba(99,210,174,.14); background:rgba(99,210,174,.04); }
.supporter-principles p { margin:0; color:#8fa6aa; font-size:7px; line-height:1.5; }

@media (orientation:portrait) and (min-width:361px) and (max-width:430px) {
  .manager-topbar { grid-template-columns:44px minmax(0,1fr) 152px clamp(104px,27.5vw,114px) 44px !important; }
  .manager-gold-brand { min-width:0; grid-template-columns:17px minmax(0,1fr) !important; column-gap:4px !important; padding-inline:5px !important; overflow:hidden; }
  .manager-gold-brand .manager-balance-icon { width:16px !important; height:16px !important; }
  .manager-gold-brand>div { min-width:0; }
  .manager-gold-brand>div>span,.manager-gold-brand>div>small { display:none !important; }
  .manager-gold-brand>div>strong { display:block; max-width:100%; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-size:8.5px !important; letter-spacing:0 !important; }
  .menu-subtab { flex:0 0 clamp(108px,29vw,124px) !important; min-width:0 !important; padding-inline:7px !important; }
  .menu-subnav-shell.can-scroll-right .menu-subnav { margin-right:0 !important; padding-right:50px !important; }
  .menu-subnav-shell.can-scroll-left .menu-subnav { margin-left:0 !important; padding-left:50px !important; }
  .foundation-path,.foundation-path>header,.foundation-path>div,.foundation-path button { min-width:0; max-width:100%; box-sizing:border-box; }
  .foundation-path>header { grid-template-columns:minmax(0,1fr) 42px !important; gap:8px !important; overflow:hidden; }
  .foundation-path button { grid-template-columns:24px minmax(0,1fr) 38px !important; gap:7px !important; padding-inline:9px !important; overflow:hidden; }
  .foundation-path button span { min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
  .foundation-path button em { min-width:0; overflow:hidden; text-overflow:clip; white-space:nowrap; text-align:right; font-size:5.5px !important; }
  .supporter-metric-grid { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .supporter-detail-grid { grid-template-columns:1fr; }
}
@media (max-width:760px) {
  .career-report-actions { grid-template-columns:1fr; }
  .career-report-action-buttons { grid-template-columns:1fr; }
  .supporter-season-card header { grid-template-columns:1fr; }
  .supporter-season-card header aside { text-align:left; }
}
@media (max-width:360px) {
  .manager-gold-brand .manager-balance-icon { display:none !important; }
  .manager-gold-brand { grid-template-columns:minmax(0,1fr) !important; padding-inline:5px !important; }
  .supporter-metric-grid { grid-template-columns:1fr; }
}

/* Build 11.91 second-pass: guarantee that the Gold Coin value is never truncated on 361–430px phones. */
@media (orientation:portrait) and (min-width:361px) and (max-width:430px) {
  .manager-gold-brand .manager-balance-icon { display:none !important; }
  .manager-gold-brand { grid-template-columns:minmax(0,1fr) !important; padding-inline:6px !important; }
  .manager-gold-brand>div>strong { text-align:center; text-overflow:clip; }
}


/* Build 11.98: inbox panel separation and clearer message-reader boundary. */
.club-mail-column {
