  background:
    linear-gradient(180deg, rgba(12, 35, 49, .98), rgba(7, 23, 34, .98)),
    repeating-linear-gradient(135deg, transparent 0 18px, rgba(98, 173, 214, .018) 19px 20px);
  box-shadow: inset 0 0 0 1px rgba(91, 161, 201, .12);
}
.club-mail-column > header {
  border-bottom-color: rgba(113, 184, 222, .22);
  background: linear-gradient(180deg, rgba(18, 45, 61, .98), rgba(10, 30, 43, .98));
}
.club-mail-list {
  position: relative;
  border-top: 1px solid rgba(83, 153, 194, .10);
  border-bottom: 3px solid rgba(82, 173, 255, .34);
  background:
    linear-gradient(180deg, rgba(9, 29, 42, .98), rgba(5, 20, 30, .98)),
    repeating-linear-gradient(0deg, transparent 0 37px, rgba(255,255,255,.014) 38px);
  box-shadow:
    inset 0 1px rgba(255,255,255,.025),
    inset 0 -10px 22px rgba(1, 8, 13, .26),
