.club-mail-row { background: rgba(8, 28, 41, .72); }
.club-mail-row:nth-child(even) { background: rgba(6, 23, 34, .84); }
.club-mail-row.unread { background: rgba(16, 50, 69, .94); }
.club-mail-row.active {
  background: linear-gradient(90deg, rgba(22, 67, 91, .98), rgba(16, 51, 70, .96));
  box-shadow: inset 4px 0 #52adff, inset 0 -2px #d5aa42;
}
.club-mail-reader {
  border-top: 1px solid rgba(103, 164, 198, .20);
  background:
    linear-gradient(180deg, rgba(4, 15, 24, .99), rgba(3, 11, 18, .99)),
    repeating-linear-gradient(0deg, transparent 0 35px, rgba(255,255,255,.010) 36px);
  box-shadow: inset 0 12px 26px rgba(0, 0, 0, .18);
}
@media (orientation: portrait) and (max-width: 900px) {
  .club-mail-column {
    border-bottom: 0;
    box-shadow: inset 0 0 0 1px rgba(91, 161, 201, .13), 0 13px 24px rgba(0,0,0,.28);
  }
  .club-mail-reader { border-top: 2px solid rgba(88, 145, 176, .24); }
}

/* -------------------------------------------------------------------------
   Build 12.00 — performance-safe free-roam inspection mode
   ------------------------------------------------------------------------- */
body[data-app-state='free-roam'] { overflow: hidden; overscroll-behavior: none; }
body[data-app-state='free-roam'] #app { display: block; padding: 0; min-height: 100dvh; }
body[data-app-state='free-roam'] .match-view { position: fixed; inset: 0; width: 100vw; height: 100dvh; max-width: none; margin: 0; border: 0; }
body[data-app-state='free-roam'] .match-view canvas { width: 100%; height: 100%; filter: none !important; }
body[data-app-state='free-roam'] .portrait-console-header,
body[data-app-state='free-roam'] .portrait-console-dock,
body[data-app-state='free-roam'] .topbar,
body[data-app-state='free-roam'] .mapTag,
body[data-app-state='free-roam'] .spectator,
body[data-app-state='free-roam'] .owned-telemetry,
body[data-app-state='free-roam'] .controls,
body[data-app-state='free-roam'] .portrait-audio-toggle,
body[data-app-state='free-roam'] .portrait-diagnostic-export,
body[data-app-state='free-roam'] .portrait-minimap-toggle,
body[data-app-state='free-roam'] .sponsor-bug,
body[data-app-state='free-roam'] .feed,
body[data-app-state='free-roam'] .status,
body[data-app-state='free-roam'] .round-result,
body[data-app-state='free-roam'] .multi-kill-banner,
body[data-app-state='free-roam'] .build-stamp,
body[data-app-state='free-roam'] .show-ui-btn,
body[data-app-state='free-roam'] .restore-view-btn { display: none !important; }
body[data-app-state='free-roam'] .match-view::before,
body[data-app-state='free-roam'] .match-view::after { display: none !important; content: none !important; }
body[data-app-state='free-roam'] .crosshair { display: block !important; opacity: .62; transform: scale(.72); }
body[data-app-state='free-roam'] .damage-overlay,
body[data-app-state='free-roam'] .death-overlay,
body[data-app-state='free-roam'] .damage-numbers { display: none !important; }

.free-roam-overlay {
  position: fixed;
  inset: 0;
  z-index: 118;
  pointer-events: none;
  color: #effaff;
  font-family: inherit;
}
.free-roam-overlay[hidden] { display: none !important; }
.free-roam-header {
  position: absolute;
  top: max(10px, env(safe-area-inset-top));
  left: max(10px, env(safe-area-inset-left));
  right: max(10px, env(safe-area-inset-right));
  min-height: 62px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 12px;
  border: 1px solid rgba(100, 217, 225, .42);
  background: linear-gradient(135deg, rgba(5, 18, 28, .92), rgba(8, 31, 40, .78));
  box-shadow: 0 10px 28px rgba(0, 0, 0, .38), inset 3px 0 0 #53d7ca;
  backdrop-filter: blur(8px);
  pointer-events: auto;
}
.free-roam-header > div:first-child { min-width: 0; display: grid; gap: 3px; }
.free-roam-header span { color: #58d9cd; font-size: 10px; letter-spacing: .18em; font-weight: 900; }
.free-roam-header strong { font-size: 18px; line-height: 1.05; letter-spacing: .08em; }
.free-roam-header small { color: #9ab0ba; font-size: 9px; letter-spacing: .1em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.free-roam-header-actions { display: flex; gap: 6px; flex: 0 0 auto; }
.free-roam-header-actions button {
  min-height: 38px;
  padding: 0 10px;
  border: 1px solid rgba(98, 194, 221, .48);
  background: rgba(7, 30, 43, .9);
  color: #dff8ff;
  font: 900 9px/1 inherit;
  letter-spacing: .12em;
  pointer-events: auto;
}
.free-roam-header-actions button.danger { border-color: rgba(255, 116, 104, .62); color: #ffb5aa; }
.free-roam-level-chip {
  position: absolute;
  top: calc(max(10px, env(safe-area-inset-top)) + 76px);
  right: max(12px, env(safe-area-inset-right));
  padding: 7px 10px;
  border: 1px solid rgba(82, 214, 203, .42);
  background: rgba(5, 18, 27, .82);
  color: #70e6d9;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .16em;
  pointer-events: none;
}
.free-roam-mobile-controls {
  position: absolute;
  left: max(14px, env(safe-area-inset-left));
  right: max(14px, env(safe-area-inset-right));
  bottom: calc(max(16px, env(safe-area-inset-bottom)) + 24px);
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 18px;
  pointer-events: none;
}
.free-roam-move-pad {
  width: 152px;
  height: 152px;
  position: relative;
  border-radius: 50%;
  border: 1px solid rgba(111, 213, 229, .25);
  background: radial-gradient(circle, rgba(8, 37, 49, .7), rgba(4, 15, 23, .32) 70%);
  pointer-events: auto;
}
.free-roam-move-pad button {
  position: absolute;
  width: 49px;
  height: 49px;
  border-radius: 12px;
  border: 1px solid rgba(112, 219, 227, .46);
  background: rgba(7, 28, 39, .86);
  color: #dffbff;
  font-size: 18px;
  font-weight: 900;
  touch-action: none;
  -webkit-user-select: none;
  user-select: none;
}
.free-roam-move-pad button.active { background: rgba(45, 154, 162, .88); border-color: #7cf6ea; transform: scale(.96); }
.free-roam-move-pad [data-free-roam-move='forward'] { left: 51px; top: 5px; }
.free-roam-move-pad [data-free-roam-move='left'] { left: 5px; top: 51px; }
.free-roam-move-pad [data-free-roam-move='back'] { left: 51px; bottom: 5px; }
.free-roam-move-pad [data-free-roam-move='right'] { right: 5px; top: 51px; }
.free-roam-look-pad {
  width: min(44vw, 220px);
  height: 124px;
  display: grid;
  place-content: center;
  gap: 5px;
  text-align: center;
  border: 1px solid rgba(112, 219, 227, .42);
  background: linear-gradient(145deg, rgba(7, 28, 39, .78), rgba(4, 14, 22, .56));
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .025);
  pointer-events: auto;
  touch-action: none;
  -webkit-user-select: none;
  user-select: none;
}
.free-roam-look-pad.active { border-color: #74eade; background: rgba(16, 69, 76, .78); }
.free-roam-look-pad span { color: #dffaff; font-size: 11px; font-weight: 900; letter-spacing: .14em; }
.free-roam-look-pad small { color: #7f9aa6; font-size: 8px; letter-spacing: .09em; }
.free-roam-help {
  position: absolute;
  left: 50%;
  bottom: max(6px, env(safe-area-inset-bottom));
  transform: translateX(-50%);
  width: max-content;
  max-width: calc(100vw - 20px);
  display: flex;
  gap: 12px;
  color: rgba(211, 237, 243, .66);
  font-size: 8px;
  letter-spacing: .08em;
  white-space: nowrap;
}

.free-roam-config-card { grid-column: 1 / -1; }
.free-roam-config-card .free-roam-map-choice { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; margin: 14px 0 12px; }
.free-roam-config-card .free-roam-map-choice button {
  min-height: 64px;
  padding: 9px;
  border: 1px solid rgba(86, 155, 178, .32);
  background: rgba(8, 25, 35, .78);
  color: #dceaf0;
  text-align: left;
}
.free-roam-config-card .free-roam-map-choice button.active { border-color: #54d8ca; box-shadow: inset 3px 0 0 #54d8ca; background: rgba(11, 50, 56, .84); }
.free-roam-config-card .free-roam-map-choice strong,
.free-roam-config-card .free-roam-map-choice small { display: block; }
.free-roam-config-card .free-roam-map-choice strong { font-size: 11px; letter-spacing: .08em; }
.free-roam-config-card .free-roam-map-choice small { margin-top: 5px; color: #78909a; font-size: 8px; line-height: 1.35; }
.free-roam-config-card .free-roam-launch { width: 100%; min-height: 46px; border-color: #54d8ca; background: linear-gradient(90deg, rgba(25, 117, 119, .82), rgba(9, 56, 67, .92)); color: #efffff; }
.free-roam-config-card .free-roam-launch:disabled { opacity: .42; }

@media (max-width: 520px) {
  .free-roam-header { align-items: flex-start; padding: 9px 10px; }
  .free-roam-header strong { font-size: 15px; }
  .free-roam-header-actions button { min-width: 42px; padding: 0 7px; font-size: 8px; }
  .free-roam-header-actions #freeRoamExportBtn { max-width: 70px; line-height: 1.2; }
  .free-roam-move-pad { width: 136px; height: 136px; }
  .free-roam-move-pad button { width: 45px; height: 45px; }
  .free-roam-move-pad [data-free-roam-move='forward'] { left: 45px; }
  .free-roam-move-pad [data-free-roam-move='left'] { top: 45px; }
  .free-roam-move-pad [data-free-roam-move='back'] { left: 45px; }
  .free-roam-move-pad [data-free-roam-move='right'] { top: 45px; }
  .free-roam-look-pad { width: min(42vw, 178px); height: 112px; }
  .free-roam-help { display: none; }
