.career-armour-inventory-list { display: grid; gap: 1px; padding: 1px; background: rgba(118,164,194,.10); }
.career-armour-inventory-item {
  position: relative;
  display: grid;
  grid-template-columns: 116px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-height: 112px;
  padding: 8px 9px;
  text-align: left;
  border: 0;
  border-left: 3px solid transparent;
  background: linear-gradient(90deg, rgba(20,38,51,.94), rgba(6,13,20,.96));
}
.career-armour-inventory-item:hover { filter: brightness(1.12); transform: none; }
.career-armour-inventory-item.selected { border-left-color: var(--accent); background: linear-gradient(90deg, rgba(48,72,86,.96), rgba(9,20,29,.96)); }
.career-armour-inventory-item.equipped { box-shadow: inset 0 0 0 1px rgba(88,174,243,.18); }
.career-armour-inventory-item > span { min-width: 0; }
.career-armour-inventory-item > span > small,
.career-armour-inventory-item > span > strong,
.career-armour-inventory-item > span > em { display: block; }
.career-armour-inventory-item > span > small { color: var(--accent); font-size: 7px; font-weight: 950; letter-spacing: .14em; }
.career-armour-inventory-item > span > strong { margin-top: 5px; color: #f5f8fb; font-size: 13px; letter-spacing: .035em; }
.career-armour-inventory-item > span > em { margin-top: 5px; color: var(--muted); font-size: 8px; font-style: normal; letter-spacing: .06em; }
.career-armour-inventory-item > b { color: rgba(180,204,219,.58); font-size: 7px; font-weight: 950; letter-spacing: .12em; writing-mode: vertical-rl; transform: rotate(180deg); }
.career-armour-inventory-item.equipped > b { color: #72c3f6; }
.career-armour-detail-preview {
  display: grid;
  place-items: center;
  min-height: 224px;
  margin: 0 0 16px;
}
.cash-armour-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); margin-top: 10px; }
.cash-armour-offer { min-width: 0; padding: 12px; border: 1px solid rgba(117, 181, 214, .17); background: rgba(4, 14, 21, .72); }
.cash-armour-offer > span,
.cash-armour-offer > strong,
.cash-armour-offer > p,
.cash-armour-offer > small { display: block; }
.cash-armour-offer > span { color: #7fcaff; font-size: 6px; font-weight: 950; letter-spacing: .13em; }
.cash-armour-offer > strong { margin-top: 5px; color: #f2f8fb; font-size: 11px; }
.cash-armour-offer > p { margin: 6px 0; color: #b5c5ce; font-size: 7.5px; line-height: 1.45; }
.cash-armour-offer > small { margin-top: 7px; color: #8ca7b8; font-size: 6px; }
.cash-armour-visual { float: right; width: 114px; min-height: 132px; margin-left: 10px; }
.cash-armour-visual .career-armour-mini3d {
  width: 114px;
  height: 132px;
  border-color: rgba(119,181,213,.12);
  background:
    radial-gradient(circle at 50% 42%, rgba(82,173,255,.16), transparent 34%),
    linear-gradient(0deg, rgba(255,255,255,.02), rgba(255,255,255,0)),
    rgba(1,7,11,.28);
}
.cash-armour-stats { display: flex; flex-wrap: wrap; gap: 5px; clear: both; }
.cash-armour-stats b { padding: 5px 6px; border: 1px solid rgba(119, 181, 213, .15); color: #c9dce6; font-size: 6px; }
.armour-store-guide { grid-template-columns: repeat(4, minmax(0, 1fr)); margin-top: 9px; }
.armour-store-guide span { color: #aabdc8; font-size: 7px; line-height: 1.4; }
.armour-store-guide b { display: block; margin-bottom: 3px; color: #e9f5fa; font-size: 7px; }
@media (max-width: 700px) {
  .career-armour-guide-grid,
  .career-armour-stat-grid,
  .armour-store-guide { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .cash-armour-grid { grid-template-columns: 1fr; }
}
@media (max-width: 430px) {
  .career-armour-guide-grid,
  .career-armour-stat-grid,
  .armour-store-guide { grid-template-columns: 1fr; }
  .career-armour-mini3d { width: 104px; height: 124px; }
  .career-armour-mini3d .career-armour-model-system { transform: translate3d(0, 3px, 0) rotateX(-12deg) rotateY(-26deg) scale(.56); }
  .cash-armour-visual { width: 92px; min-height: 118px; }
  .cash-armour-visual .career-armour-mini3d { width: 92px; height: 118px; }
  .cash-armour-visual .career-armour-mini3d .career-armour-model-system { --armour-store-scale: .58; }
}

@media (prefers-reduced-motion: reduce) {
  .cash-armour-visual .career-armour-model-system { animation: none; }
  .career-armour-showcase .career-armour-model-system { transition: none; }
}

/* Build 12.17: primary/sidearm clarity and spectator armour integrity. */
.armour-hud { margin-top: 5px; display: grid; grid-template-columns: auto minmax(58px, 1fr); align-items: center; gap: 7px; }
.armour-hud[hidden] { display: none !important; }
.armour-hud > span { color: #9ed8ff; font-size: 7px; font-weight: 950; letter-spacing: .08em; white-space: nowrap; }
.armour-hud > i { display: block; height: 4px; overflow: hidden; border-radius: 99px; background: rgba(120,190,230,.16); }
.armour-hud > i > b { display: block; width: 100%; height: 100%; transform-origin: left; background: linear-gradient(90deg,#4f93bf,#8fd7ff); transition: transform .16s ease, background .18s ease; }
.career-loadout-slot-summary { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:8px; margin-top:10px; }
.career-loadout-slot-summary article { border:1px solid rgba(255,255,255,.1); border-radius:10px; padding:9px; background:rgba(6,14,24,.5); }
.career-loadout-slot-summary span { display:block; color:var(--muted); font-size:7px; font-weight:900; letter-spacing:.12em; }
.career-loadout-slot-summary strong { display:block; margin-top:4px; font-size:10px; }
.career-loadout-slot-summary small { display:block; margin-top:3px; color:var(--muted); font-size:7px; }
.career-weapon-tradeoffs { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:8px; margin:10px 0; }
.career-weapon-tradeoffs article { border-radius:10px; border:1px solid rgba(255,255,255,.1); padding:9px; background:rgba(5,12,20,.52); }
.career-weapon-tradeoffs article.good { border-color:rgba(88,214,141,.28); }
.career-weapon-tradeoffs article.bad { border-color:rgba(255,120,120,.25); }
.career-weapon-tradeoffs strong { display:block; font-size:8px; letter-spacing:.12em; }
.career-weapon-tradeoffs ul { margin:7px 0 0; padding-left:16px; color:var(--muted); font-size:8px; line-height:1.45; }
.career-slot-actions { display:flex; gap:7px; flex-wrap:wrap; }
.career-slot-actions button { flex:1 1 140px; }
@media (max-width:520px) { .career-loadout-slot-summary,.career-weapon-tradeoffs { grid-template-columns:1fr; } }

