/* Build 12.39 passive squad dynamics */
.squad-dynamics-panel {
  margin: 14px 0;
  border: 1px solid rgba(111, 205, 184, .30);
  background: linear-gradient(145deg, rgba(8, 22, 29, .98), rgba(5, 14, 20, .98));
  overflow: hidden;
}
.squad-dynamics-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(170px, .34fr);
  gap: 16px;
  align-items: stretch;
  padding: 16px;
  border-bottom: 1px solid rgba(255, 255, 255, .08);
}
.squad-dynamics-head > div > span,
.squad-dynamics-head aside > span,
.squad-dynamics-secondary article > span,
.squad-dynamics-developing > span,
.squad-dynamics-profile-buff > span,
.career-report-dynamics article > span {
  display: block;
  color: #76d9ba;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .15em;
  text-transform: uppercase;
}
.squad-dynamics-head > div > strong {
  display: block;
  margin-top: 5px;
  color: #eef8f5;
  font-size: 19px;
  letter-spacing: .055em;
}
.squad-dynamics-head > div > p {
  max-width: 760px;
  margin: 7px 0 0;
  color: #a4b9b8;
  font-size: 10px;
  line-height: 1.5;
}
.squad-dynamics-head aside {
  position: relative;
  min-width: 0;
  padding: 13px 54px 13px 13px;
  border: 1px solid rgba(255, 255, 255, .10);
  background: rgba(255, 255, 255, .035);
}
.squad-dynamics-head aside strong,
.squad-dynamics-head aside small { display: block; }
.squad-dynamics-head aside strong { margin-top: 5px; color: #f0f8f5; font-size: 14px; }
.squad-dynamics-head aside b {
  position: absolute;
  top: 13px;
  right: 13px;
  color: #75dfb8;
  font-size: 27px;
}
.squad-dynamics-head aside small { margin-top: 7px; color: #9cb1b1; font-size: 8px; line-height: 1.4; }
.squad-dynamics-head aside.elite { border-color: rgba(118, 223, 184, .48); background: rgba(28, 75, 59, .30); }
.squad-dynamics-head aside.trusted { border-color: rgba(92, 190, 205, .38); }
.squad-dynamics-policy {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  align-items: center;
  padding: 10px 16px;
  border-bottom: 1px solid rgba(255, 255, 255, .06);
}
.squad-dynamics-policy b { margin-right: 4px; color: #e5f1ef; font-size: 9px; letter-spacing: .11em; }
.squad-dynamics-policy span {
  padding: 5px 8px;
  border: 1px solid rgba(118, 217, 186, .20);
  background: rgba(118, 217, 186, .055);
  color: #a9c7c0;
  font-size: 8px;
  letter-spacing: .065em;
}
.squad-dynamics-pairs {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 9px;
  padding: 14px 16px;
}
.squad-dynamics-pair {
  min-width: 0;
  padding: 12px;
  text-align: left;
  border: 1px solid rgba(255, 255, 255, .10);
  background: rgba(9, 24, 31, .88);
}
.squad-dynamics-pair:hover { border-color: rgba(118, 217, 186, .44); }
.squad-dynamics-pair header { display: flex; justify-content: space-between; gap: 10px; align-items: center; }
.squad-dynamics-pair header span { color: #75dcb8; font-size: 8px; font-weight: 900; letter-spacing: .12em; }
.squad-dynamics-pair header b { color: #e9f8f2; font-size: 18px; }
.squad-dynamics-pair > strong,
.squad-dynamics-pair > small,
.squad-dynamics-pair > footer { display: block; }
.squad-dynamics-pair > strong { margin-top: 6px; color: #f3f8f7; font-size: 13px; }
.squad-dynamics-pair > small { margin-top: 4px; color: #8fa8a7; font-size: 8px; letter-spacing: .06em; }
.squad-dynamics-pair > i {
  display: block;
  height: 5px;
  margin: 10px 0 0;
  overflow: hidden;
  background: rgba(255, 255, 255, .07);
}
.squad-dynamics-pair > i em { display: block; height: 100%; background: linear-gradient(90deg, #4ca7b9, #73dbb5); }
.squad-dynamics-pair > p { min-height: 30px; margin: 8px 0 0; color: #9fb4b2; font-size: 9px; line-height: 1.45; }
.squad-dynamics-pair > footer { margin-top: 8px; color: #70c9b2; font-size: 8px; font-weight: 850; letter-spacing: .075em; }
.squad-dynamics-pair.tier-3,
.squad-dynamics-pair.tier-4 { border-color: rgba(118, 217, 186, .38); background: rgba(18, 48, 44, .56); }
.squad-dynamics-empty {
  grid-column: 1 / -1;
  padding: 16px;
  border: 1px dashed rgba(118, 217, 186, .22);
  text-align: center;
}
.squad-dynamics-empty strong { color: #e7f3f0; font-size: 12px; }
.squad-dynamics-empty p { max-width: 620px; margin: 7px auto 0; color: #99afad; font-size: 9px; line-height: 1.5; }
.squad-dynamics-developing { padding: 0 16px 14px; }
.squad-dynamics-developing > div { display: flex; flex-wrap: wrap; gap: 7px; margin-top: 7px; }
.squad-dynamics-developing button { min-width: 0; flex: 1 1 190px; padding: 9px 10px; text-align: left; }
.squad-dynamics-developing button strong,
.squad-dynamics-developing button small { display: block; }
.squad-dynamics-developing button strong { color: #e8f2f0; font-size: 9px; }
.squad-dynamics-developing button small { margin-top: 4px; color: #8ba3a1; font-size: 8px; }
.squad-dynamics-secondary {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1px;
  background: rgba(255, 255, 255, .07);
  border-top: 1px solid rgba(255, 255, 255, .06);
}
.squad-dynamics-secondary article { min-width: 0; padding: 14px 16px; background: rgba(6, 17, 23, .98); }
.squad-dynamics-secondary article strong { display: block; margin-top: 6px; color: #edf6f4; font-size: 12px; }
.squad-dynamics-secondary article p { margin: 7px 0 0; color: #9cb0af; font-size: 9px; line-height: 1.5; }
.squad-dynamics-secondary article button { min-height: 36px; margin-top: 10px; }
.squad-dynamics-rotation.positive strong { color: #74dab7; }
.squad-dynamics-mini-badge {
  display: block;
  margin: 8px 0 0;
  padding: 6px 8px;
  border: 1px solid rgba(118, 217, 186, .22);
  background: rgba(118, 217, 186, .06);
  color: #7ddabf;
  font-size: 8px;
  font-weight: 850;
  letter-spacing: .065em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.squad-dynamics-mini-badge.developing { color: #91a7a5; border-color: rgba(255, 255, 255, .10); background: rgba(255, 255, 255, .025); }
.squad-dynamics-mini-badge.tier-3,
.squad-dynamics-mini-badge.tier-4 { border-color: rgba(118, 217, 186, .45); color: #91efd0; }
.squad-dynamics-profile { margin: 12px 0; }
.squad-dynamics-profile-buff { padding: 12px; border: 1px solid rgba(118, 217, 186, .24); background: rgba(118, 217, 186, .055); }
.squad-dynamics-profile-buff strong,
.squad-dynamics-profile-buff small { display: block; }
.squad-dynamics-profile-buff strong { margin-top: 5px; color: #edf7f4; font-size: 12px; }
.squad-dynamics-profile-buff small { margin-top: 6px; color: #9fb3b0; font-size: 9px; line-height: 1.45; }
.squad-dynamics-profile-buff.developing { border-color: rgba(255, 255, 255, .10); background: rgba(255, 255, 255, .025); }
.squad-dynamics-profile-pairs { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 7px; margin-top: 9px; }
.squad-dynamics-profile-pairs button { min-width: 0; padding: 10px; text-align: left; }
.squad-dynamics-profile-pairs button span,
.squad-dynamics-profile-pairs button strong,
.squad-dynamics-profile-pairs button small { display: block; }
.squad-dynamics-profile-pairs button span { color: #75d9ba; font-size: 8px; letter-spacing: .1em; }
.squad-dynamics-profile-pairs button strong { margin-top: 4px; color: #eef6f4; font-size: 11px; }
.squad-dynamics-profile-pairs button small { margin-top: 5px; color: #91a8a5; font-size: 8px; line-height: 1.4; }
.squad-dynamics-profile-empty { padding: 12px; color: #93a8a6; font-size: 9px; line-height: 1.45; }
.squad-dynamics-profile-mentor { margin: 10px 0 0; color: #9db2af; font-size: 9px; line-height: 1.45; }
.squad-dynamics-profile-mentor strong { color: #73d7b8; }
.career-report-dynamics { margin: 12px 0; border: 1px solid rgba(118, 217, 186, .25); background: rgba(8, 23, 28, .78); }
.career-report-dynamics > .career-section-head { padding: 13px; border-bottom: 1px solid rgba(255, 255, 255, .07); }
.career-report-dynamics-milestones { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; padding: 12px; }
.career-report-dynamics article { padding: 12px; border: 1px solid rgba(118, 217, 186, .22); background: rgba(118, 217, 186, .045); }
.career-report-dynamics article strong,
.career-report-dynamics article small { display: block; }
.career-report-dynamics article strong { margin-top: 5px; color: #eff8f5; font-size: 12px; }
.career-report-dynamics article small { margin-top: 6px; color: #9cb1ae; font-size: 9px; line-height: 1.45; }
.career-report-dynamics-progress,
.career-report-dynamics-quiet { margin: 12px; }
.career-report-dynamics-quiet { color: #9db1af; font-size: 9px; line-height: 1.45; }

@media (max-width: 760px) {
  .squad-dynamics-head { grid-template-columns: 1fr; }
  .squad-dynamics-pairs,
  .squad-dynamics-secondary,
  .career-report-dynamics-milestones { grid-template-columns: 1fr; }
}
@media (max-width: 430px) {
  .squad-dynamics-panel { margin: 10px 0; }
  .squad-dynamics-head { padding: 12px; }
  .squad-dynamics-policy { padding: 9px 12px; }
  .squad-dynamics-pairs { padding: 12px; }
  .squad-dynamics-developing { padding: 0 12px 12px; }
  .squad-dynamics-profile-pairs { grid-template-columns: 1fr; }
  .squad-dynamics-mini-badge { white-space: normal; line-height: 1.35; }
}

