/* =====================================================================
   FOOTBALL-MANAGER THEME OVERRIDE
   Deep navy/pitch-green palette, squared-off "boardroom" panels, gold
   accent for key numbers/CTAs, flat data-table rows. Cosmetic only —
   no layout, grid, or sizing properties are touched here so gameplay
   HUD and responsive breakpoints keep working exactly as before.
   ===================================================================== */
:root {
  --accent: #e3a942;          /* boardroom gold */
  --accent-2: #ffcf7a;        /* gold highlight */
  --pitch: #3fbd6c;           /* pitch green — positive / live states */
  --pitch-dark: #1f7a44;
  --muted: #8ea0b3;
  --blue: #4fa6e8;
  --red: #e05a5a;
  --fm-bg-1: #0a121b;
  --fm-bg-2: #0d1822;
  --fm-panel-1: #16222f;
  --fm-panel-2: #101a24;
  --fm-border: rgba(160, 190, 210, .16);
  --fm-border-strong: rgba(227, 169, 66, .38);
  --fm-radius: 7px;
}

/* Backdrop chrome (topbar / HUD shell) — squarer, cooler, gold hairline */
.brand, .round, .spectator, .controls, .status, .mapTag, .hud-actions {
  background: linear-gradient(180deg, var(--fm-panel-1), var(--fm-panel-2)) !important;
  border: 1px solid var(--fm-border) !important;
  border-top: 1px solid var(--fm-border-strong) !important;
  box-shadow: 0 10px 26px rgba(0,0,0,.45) !important;
}
.round.match-point { border-color: rgba(227,169,66,.7) !important; box-shadow: 0 0 22px rgba(227,169,66,.16), 0 10px 26px rgba(0,0,0,.45) !important; }
button { background: rgba(255,255,255,.05) !important; border: 1px solid var(--fm-border) !important; border-radius: 6px !important; }
button:active { background: rgba(255,255,255,.12) !important; }
button.primary {
  background: linear-gradient(180deg, var(--accent-2), var(--accent)) !important;
  border-color: rgba(227,169,66,.7) !important;
  color: #1a1206 !important;
  text-shadow: none !important;
}

/* Menu shell: sidebar reads like a club-crest boardroom rail */
.menu-sidebar, .menu-content {
  background: linear-gradient(180deg, var(--fm-bg-2), var(--fm-bg-1)) !important;
  border: 1px solid var(--fm-border) !important;
  border-radius: 10px !important;
}
.menu-sidebar {
  background:
    linear-gradient(180deg, rgba(63,189,108,.05), transparent 40%),
    linear-gradient(180deg, var(--fm-bg-2), var(--fm-bg-1)) !important;
  border-right: 2px solid var(--fm-border-strong) !important;
}
.menu-sidebar::before { background: linear-gradient(180deg, rgba(227,169,66,.16), transparent 26%) !important; }
.menu-content::before { background: radial-gradient(circle at 78% 10%, rgba(63,189,108,.07), transparent 34%), linear-gradient(180deg, rgba(255,255,255,.02), transparent 24%) !important; }

.menu-kicker { color: var(--accent) !important; text-transform: uppercase; }
.menu-badge { color: var(--accent) !important; border-radius: 4px !important; }

/* Nav rail — flat rows, gold rail on the active tab (classic FM list nav) */
.menu-tab {
  border-radius: 6px !important;
  background: rgba(255,255,255,.03) !important;
  border: 1px solid var(--fm-border) !important;
  box-shadow: none !important;
}
.menu-tab::before { width: 3px !important; background: rgba(255,255,255,.10) !important; }
.menu-tab.active, .menu-tab.primary {
  background: linear-gradient(90deg, rgba(63,189,108,.16), rgba(63,189,108,.03)) !important;
  border-color: rgba(63,189,108,.45) !important;
  box-shadow: inset 0 0 0 1px rgba(63,189,108,.10) !important;
}
.menu-tab.active::before, .menu-tab.primary::before { background: linear-gradient(180deg, var(--pitch), var(--pitch-dark)) !important; }

/* Hero / card panels — squared corners, gold cap-line, boardroom fill */
.menu-hero-main, .menu-hero-side, .menu-card, .menu-setting-card, .menu-info-tile {
  background: linear-gradient(180deg, var(--fm-panel-1), var(--fm-panel-2)) !important;
  border: 1px solid var(--fm-border) !important;
  border-top: 2px solid var(--fm-border-strong) !important;
  border-radius: var(--fm-radius) !important;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.02) !important;
}
.menu-hero-main h2, .menu-card h3, .menu-setting-card h3 { letter-spacing: .03em !important; }
.menu-briefing-panel::after { background: radial-gradient(circle, rgba(63,189,108,.14), transparent 68%) !important; }
.menu-side-operator { color: var(--accent-2) !important; }

.menu-pill {
  border-radius: 4px !important;
  background: rgba(255,255,255,.03) !important;
  border: 1px solid var(--fm-border) !important;
}
.menu-pill::before { color: var(--accent) !important; }

/* Section headers — underline rule like an FM screen banner */
.career-section-head {
  border-bottom: 2px solid var(--fm-border-strong) !important;
  padding-bottom: 8px !important;
}
.career-section-head span { color: var(--pitch) !important; }

/* Data tables (squad / transfer market lists) — flat rows, zebra tint, gold header */
.team-market-table-head {
  background: #0e1620 !important;
  border: 1px solid var(--fm-border) !important;
  color: var(--accent) !important;
  border-radius: 5px 5px 0 0 !important;
}
.team-market-row {
  border: 1px solid var(--fm-border) !important;
  border-radius: 4px !important;
  background: rgba(255,255,255,.015) !important;
}
.team-market-list .team-market-row:nth-child(even) { background: rgba(255,255,255,.035) !important; }
.team-market-row:hover { background: rgba(63,189,108,.09) !important; border-color: rgba(63,189,108,.35) !important; }
.team-market-rating strong { color: var(--pitch) !important; }
.team-attribute-row i b { background: linear-gradient(90deg, var(--pitch-dark), var(--pitch)) !important; }

.menu-danger-trigger { border-color: rgba(224,90,90,.5) !important; color: #ffb3b3 !important; }

/* Thin boardroom scrollbars for the menu panes */
.menu-sidebar::-webkit-scrollbar, .menu-content::-webkit-scrollbar { width: 8px; }
.menu-sidebar::-webkit-scrollbar-thumb, .menu-content::-webkit-scrollbar-thumb { background: rgba(227,169,66,.35); border-radius: 4px; }
.menu-sidebar::-webkit-scrollbar-track, .menu-content::-webkit-scrollbar-track { background: transparent; }

/* =====================================================================
   BUILD 12.71 · COMPACT RECRUITMENT CARDS & COMPARISON TRAY
   Candidate browsing now uses compact two-faced cards. The front keeps the
   decision essentials visible; the reverse holds the deeper scout context.
   Comparison selections remain visible in a sticky tray and expand into the
   established squad-fit decision workspace only when requested.
   ===================================================================== */
.recruitment-candidate-zone .team-market-table-head { display: none !important; }
.recruitment-candidate-zone .team-market-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(286px, 1fr));
  align-items: start;
  gap: 12px;
  margin-top: 12px;
}
.recruitment-market-row.recruitment-candidate-card {
  display: block !important;
  position: relative;
  min-width: 0;
  height: 342px;
  padding: 0 !important;
  overflow: hidden;
  perspective: 1200px;
  contain: layout paint;
  border: 1px solid rgba(198, 212, 224, .24) !important;
  border-left: 4px solid rgba(162, 184, 202, .86) !important;
  border-radius: 8px !important;
  background: linear-gradient(180deg, #24313e, #141d27 58%, #101821) !important;
  box-shadow: 0 12px 28px rgba(0, 0, 0, .28), inset 0 1px rgba(255, 255, 255, .065), inset 0 0 0 1px rgba(214, 226, 236, .03) !important;
}
.recruitment-market-row.recruitment-candidate-card.shortlisted { border-left-color: #e3a942 !important; }
.recruitment-market-row.recruitment-candidate-card.compared { border-left-color: #69dab5 !important; }
.recruitment-market-row.recruitment-candidate-card:hover {
  background: linear-gradient(180deg, #283746, #17212c 58%, #111923) !important;
  border-color: rgba(214, 224, 233, .38) !important;
  border-left-color: inherit !important;
}
.recruitment-card-stage {
  position: relative;
  width: 100%;
  height: 100%;
  transform-style: preserve-3d;
  transition: transform .46s cubic-bezier(.2, .75, .2, 1);
}
.recruitment-candidate-card.is-flipped .recruitment-card-stage { transform: rotateY(180deg); }
.recruitment-card-face {
  position: absolute;
  inset: 0;
  min-width: 0;
  display: grid;
  align-content: start;
  gap: 9px;
  padding: 13px;
  overflow: hidden;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, .11), rgba(255, 255, 255, 0) 38%),
    linear-gradient(180deg, rgba(195, 210, 221, .14), rgba(120, 137, 151, .06) 24%, transparent 46%),
    linear-gradient(180deg, #223141, #17222d 54%, #101821);
}
.recruitment-card-face[aria-hidden='true'] { pointer-events: none; }
.recruitment-card-back { transform: rotateY(180deg); }
.recruitment-card-identity {
  min-width: 0;
  display: grid !important;
  gap: 4px;
  padding: 0 0 9px !important;
  border: 0 !important;
  border-bottom: 1px solid rgba(160, 190, 210, .16) !important;
  border-radius: 0 !important;
  background: transparent !important;
  text-align: left;
}
.recruitment-card-identity > span {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.recruitment-card-identity b,
.recruitment-card-identity em {
  min-width: 0;
  font-style: normal;
  font-size: 8px;
  font-weight: 950;
  letter-spacing: .1em;
}
.recruitment-card-identity b { color: var(--pitch); }
.recruitment-card-identity em { color: var(--accent); text-align: right; }
.recruitment-card-identity > strong {
  overflow: hidden;
  color: #f5f8fa;
  font-size: 17px;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.recruitment-card-identity > small {
  overflow: hidden;
  color: #9aabba;
  font-size: 9px;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.recruitment-card-front > .recruitment-recommendation-badges {
  position: static;
  display: flex;
  min-height: 18px;
  flex-wrap: wrap;
  gap: 4px;
}
.recruitment-card-front > .recruitment-recommendation-badges b {
  padding: 3px 6px;
  border: 1px solid rgba(227, 169, 66, .3);
  border-radius: 3px;
  color: #f2c66b;
  background: rgba(227, 169, 66, .07);
  font-size: 7px;
  letter-spacing: .065em;
}
.recruitment-card-front > .recruitment-knowledge {
  width: 100%;
  margin: 0;
}
.recruitment-card-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 5px;
}
.recruitment-card-metrics > div {
  min-width: 0;
  display: grid;
  align-content: start;
  gap: 3px;
  min-height: 65px;
  padding: 7px 6px;
  border: 1px solid rgba(190, 205, 217, .14);
  border-top: 2px solid rgba(182, 199, 213, .46);
  background: linear-gradient(180deg, rgba(205, 217, 226, .07), rgba(9, 17, 24, .5));
}
.recruitment-card-metrics span,
.recruitment-card-metrics small {
  overflow: hidden;
  color: #8395a4;
  font-size: 7px !important;
  font-weight: 900;
  letter-spacing: .075em;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.recruitment-card-metrics > div > strong {
  overflow: hidden;
  color: #f4f7f8 !important;
  font-size: 12px !important;
  line-height: 1.05;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.recruitment-card-metrics .scouting-stars {
  min-width: 0;
  gap: 1px;
}
.recruitment-card-metrics .scouting-stars > span { font-size: 8px !important; }
.recruitment-card-metrics .scouting-stars > span > span {
  width: .98em;
  filter: drop-shadow(0 0 5px rgba(246, 217, 127, .16));
}
.recruitment-card-metrics .scouting-stars small { display: none !important; }
.recruitment-card-fit {
  min-width: 0;
  display: grid;
  gap: 3px;
  padding: 8px 9px;
  border: 1px solid rgba(184, 201, 214, .22);
  border-left: 3px solid #b7ccdb;
  background: linear-gradient(180deg, rgba(201, 214, 224, .1), rgba(19, 31, 42, .54));
}
.recruitment-card-fit.positive { border-left-color: #8fc0a1; background: linear-gradient(180deg, rgba(143, 192, 161, .14), rgba(19, 31, 42, .54)); }
.recruitment-card-fit.prospect { border-left-color: #d4bb89; background: linear-gradient(180deg, rgba(212, 187, 137, .14), rgba(19, 31, 42, .54)); }
.recruitment-card-fit > span {
  color: #b7def0;
  font-size: 7px;
  font-weight: 950;
  letter-spacing: .08em;
}
.recruitment-card-fit > strong {
  display: -webkit-box;
  overflow: hidden;
  color: #edf3f5;
  font-size: 9px;
  line-height: 1.35;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}
.recruitment-card-fit > small {
  overflow: hidden;
  color: #92a4b1;
  font-size: 7px;
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.recruitment-card-actions {
  align-self: end;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 5px;
  margin-top: auto;
}
.recruitment-card-actions button {
  min-width: 0;
  min-height: 38px;
  padding: 0 5px;
  overflow: hidden;
  font-size: 7px;
  font-weight: 950;
  letter-spacing: .04em;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.recruitment-card-actions.back-actions { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.recruitment-card-actions.recruitment-card-actions-utility {
  grid-template-columns: 42px minmax(84px, .9fr) minmax(92px, 1fr) minmax(108px, 1.15fr);
}
.recruitment-card-actions.recruitment-card-actions-utility.back-actions {
  grid-template-columns: 42px minmax(92px, 1fr) minmax(108px, 1fr) minmax(108px, 1.15fr);
}
.recruitment-card-icon-action {
  min-width: 42px !important;
  width: 42px;
  padding: 0 !important;
  justify-content: center;
  font-size: 14px !important;
  line-height: 1;
}
.recruitment-card-utility-action {
  min-width: 84px;
}
.recruitment-card-actions .compare-toggle.active {
  border-color: rgba(105, 218, 181, .62) !important;
  color: #baf3df !important;
  background: rgba(40, 130, 102, .2) !important;
}
.recruitment-card-back > header {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  gap: 8px;
  padding-bottom: 9px;
  border-bottom: 1px solid rgba(160, 190, 210, .16);
}
.recruitment-card-back > header > div { min-width: 0; }
.recruitment-card-back > header span,
.recruitment-card-back > header strong,
.recruitment-card-back > header small { display: block; }
.recruitment-card-back > header span { color: var(--accent); font-size: 7px; font-weight: 950; letter-spacing: .09em; }
.recruitment-card-back > header strong { margin-top: 4px; color: #f5f8fa; font-size: 15px; }
.recruitment-card-back > header small { margin-top: 3px; color: #93a6b4; font-size: 8px; }
.recruitment-card-back > header button {
  min-width: 84px;
  min-height: 34px;
  padding: 0 8px;
  color: #f0c36b;
  font-size: 7px;
  font-weight: 950;
}
.recruitment-card-back-body {
  min-height: 0;
  display: grid;
  align-content: start;
  gap: 8px;
  overflow: auto;
  scrollbar-width: thin;
}
.recruitment-card-scout-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 5px;
}
.recruitment-card-scout-grid article {
  min-width: 0;
  display: grid;
  align-content: start;
  gap: 4px;
  min-height: 75px;
  padding: 8px;
  border: 1px solid rgba(192, 206, 217, .14);
  background: linear-gradient(180deg, rgba(202, 215, 224, .07), rgba(7, 15, 22, .44));
}
.recruitment-card-scout-grid span,
.recruitment-card-impact-detail > span {
  color: #76c9ec;
  font-size: 7px;
  font-weight: 950;
  letter-spacing: .085em;
}
.recruitment-card-scout-grid strong {
  color: #edf3f6;
  font-size: 8px;
  line-height: 1.35;
}
.recruitment-card-scout-grid small {
  display: -webkit-box;
  overflow: hidden;
  color: #8fa2af;
  font-size: 7px;
  line-height: 1.35;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}
.recruitment-card-impact-detail {
  display: grid;
  gap: 3px;
  padding: 8px 9px;
  border-left: 3px solid #b7ccdb;
