.recruitment-card-impact-detail strong { color: #f1f5f6; font-size: 9px; }
.recruitment-card-impact-detail p,
.recruitment-card-impact-detail small { margin: 0; color: #94a6b2; font-size: 7px; line-height: 1.35; }

.recruitment-comparison-tray {
  position: sticky;
