.interface-background-card {
  align-content: start;
}
.interface-background-preview {
  position: relative;
  min-height: 76px;
  margin-top: 12px;
  padding: 12px;
  overflow: hidden;
  border: 1px solid rgba(126, 193, 222, .24);
  border-radius: 8px;
