  font-size: 8px;
  font-weight: 950;
  letter-spacing: .12em;
}
.interface-background-preview > strong {
  margin-top: 5px;
  color: #f0f6f8;
  font-size: 15px;
  letter-spacing: .06em;
}
.interface-background-preview > i {
  position: absolute;
  bottom: 10px;
  width: 24%;
  height: 23px;
  border: 1px solid rgba(183, 211, 224, .17);
  border-radius: 5px;
  background: linear-gradient(180deg, rgba(24, 42, 55, .96), rgba(9, 21, 31, .96));
  box-shadow: 0 6px 14px rgba(0,0,0,.2);
}
.interface-background-preview > i:nth-of-type(1) { right: 12px; }
.interface-background-preview > i:nth-of-type(2) { right: calc(24% + 18px); }
.interface-background-preview > i:nth-of-type(3) { right: calc(48% + 24px); }
.interface-background-picker {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 56px auto;
  align-items: center;
  gap: 10px;
  margin-top: 12px;
  padding: 10px 11px;
  border: 1px solid rgba(126, 174, 205, .16);
  border-radius: 7px;
  background: rgba(4, 14, 22, .5);
}
.interface-background-picker > span {
  color: #a5b8c4;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: .1em;
}
