  width: 56px;
  min-width: 56px;
  height: 42px;
  min-height: 42px;
  padding: 3px;
  overflow: hidden;
  border: 1px solid rgba(139, 205, 229, .32);
  border-radius: 6px;
  background: rgba(255,255,255,.04);
  cursor: pointer;
}
.interface-background-picker input[type='color']::-webkit-color-swatch-wrapper { padding: 0; }
.interface-background-picker input[type='color']::-webkit-color-swatch { border: 0; border-radius: 3px; }
.interface-background-picker input[type='color']::-moz-color-swatch { border: 0; border-radius: 3px; }
.interface-background-picker output {
  min-width: 72px;
  color: #e6eef2;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .055em;
  text-align: right;
}
.interface-background-presets {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 7px;
  margin-top: 10px;
}
