  }

  .opponent-preparation-quick-read dl > div {
    padding: 11px 12px !important;
  }

  .opponent-preparation-quick-read dt {
    font-size: 11px !important;
  }

  .opponent-preparation-quick-read dd {
    margin-top: 6px !important;
